comms.text:
@1 וַהֲווֹ חַיֵּי שָׂרָה מְאָה וְעֶשְׂרִין וּשְׁבַע שְׁנִין שְׁנֵי חַיֵּי שָׂרָה:
@2 וּמִיתַת שָׂרָה בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן בְּאַרְעָא דִּכְנָעַן וַאֲתָא אַבְרָהָם לְמִסְפְּדָה לְשָׂרָה וּלְמִבְכַּהּ:
@3 וְקָם אַבְרָהָם מֵעַל אַפֵּי מִיתֵהּ וּמַלֵּל עִם בְּנֵי חִתָּאָה לְמֵימָר:
@4 דַּיָּר וְתוֹתַב אֲנָא עִמְּכוֹן הָבוּ לִי אַחֲסָנַת קְבוּרָא עִמְּכוֹן וְאִקְבַּר מִיתִי מִן קֳדָמָי:
@5 וַאֲתִיבוּ בְנֵי חִתָּאָה יָת אַבְרָהָם לְמֵימָר לֵהּ:
@6 קַבֵּל מִנָּנָא רִבּוֹנָנָא רַב קֳדָם יְיָ אַתְּ בֵּינָנָא בִּשְׁפַר קִבְרָנָא קְבַר יָת מִיתָךְ אֱנַשׁ מִנָּנָא יָת קִבְרֵהּ לָא יִמְנַע מִנָּךְ מִלְמִקְבַּר מִיתָךְ:
@7 וְקָם אַבְרָהָם וּסְגִיד לְעַמָּא דְאַרְעָא לִבְנֵי חִתָּאָה:
@8 וּמַלֵּל עִמְּהוֹן לְמֵימָר אִם אִית רַעֲוָא בְנַפְשְׁכוֹן לְמִקְבַּר יָת מִיתִי מִן קֳדָמַי קַבִּילוּ מִנִּי וּבְעוּ לִי מִן עֶפְרוֹן בַּר צוֹחַר:
@9 וְיִתֶּן לִי יָת מְעָרַת כָּפֶלְתָּא דִּי לֵהּ דִּי בִּסְטַר חַקְלֵהּ בְּכַסְפָּא שְׁלִים יִתְּנִינַהּ לִי בֵּינֵיכוֹן לְאַחֲסָנַת קְבוּרָא:
@10 וְעֶפְרוֹן יָתֵב בְּגוֹ בְּנֵי חִתָּאָה וְאָתֵיב עֶפְרוֹן חִתָּאָה יָת אַבְרָהָם קֳדָם בְּנֵי חִתָּאָה לְכֹל עָלֵי תְּרַע קַרְתֵּהּ לְמֵימָר:
@11 לָא רִבּוֹנִי קַבֵּיל מִנִּי חַקְלָא יְהָבִית לָךְ וּמְעַרְתָּא דִּי בֵהּ לָךְ יְהָבִיתַהּ לְעֵינֵי בְנֵי עַמִּי יְהָבִיתַהּ לָךְ קְבַר מִיתָךְ:
@12 וּסְגִיד אַבְרָהָם קֳדָם עַמָּא דְאַרְעָא:
@13 וּמַלֵּיל עִם עֶפְרוֹן קֳדָם עַמָּא דְאַרְעָא לְמֵימָר בְּרַם אִם אַתְּ עָבֵד לִי טִיבוּ קַבֵּל מִנִּי אֶתֵּן כַּסְפָּא דְמֵי חַקְלָא סַב מִנִּי וְאֶקְבַּר יָת מִיתִי תַּמָּן:
@14 וְאָתֵיב עֶפְרוֹן יָת אַבְרָהָם לְמֵימָר לֵהּ:
@15 רִבּוֹנִי קַבֵּל מִנִּי אַרְעָא שַׁוְיָא אַרְבַּע מְאָה סִלְעִין דִּכְסַף בֵּינָא וּבֵינָךְ מַה הִיא וְיָת מִיתָךְ קְבַר:
@16 וְקַבֵּל אַבְרָהָם מִן עֶפְרוֹן וּתְקַל אַבְרָהָם לְעֶפְרוֹן יָת כַּסְפָּא דְּמַלֵּיל קֳדָם בְּנֵי חִתָּאָה אַרְבַּע מְאָה סִלְעִין דִּכְסַף מִתְקַבֵּל סְחוֹרָא (נ''י דְּמִתְקַבֵּל סְחוֹרָתָא) בְּכָל מְדִינְתָּא:
@17 וְקָם חֲקַל עֶפְרוֹן דִּי בְּכָפֶלְתָּא דִּי קֳדָם מַמְרֵא חַקְלָא וּמְעַרְתָּא דִּי בֵהּ וְכָל אִילָנֵי דִּי בְחַקְלָא דִּי בְכָל תְּחוּמֵהּ סְחוֹר סְחוֹר:
@18 לְאַבְרָהָם לִזְבִינוֹהִי לְעֵינֵי בְּנֵי חִתָּאָה בְּכֹל עָלֵי תְּרַע קַרְתֵּהּ:
@19 וּבָתַר כֵּן קְבַר אַבְרָהָם יָת שָׂרָה אִתְּתֵהּ בִּמְעָרַת חֲקַל כָּפֶלְתָּא עַל אַפֵּי מַמְרֵא הִיא חֶבְרוֹן בְּאַרְעָא דִּכְנָעַן:
@20 וְקָם חַקְלָא וּמְעַרְתָּא דִּי בֵהּ לְאַבְרָהָם לְאַחֲסָנַת קְבוּרָא מִן בְּנֵי חִתָּאָה:
@21 וְאַבְרָהָם סִיב עָל בְּיוֹמִין וַיְיָ בְּרִיךְ יָת אַבְרָהָם בְּכֹלָא:
@22 וַאֲמַר אַבְרָהָם לְעַבְדֵהּ סָבָא דְבֵיתֵהּ דְּשַׁלִּיט בְּכָל דִי לֵהּ שַׁוִּי כְעַן יְדָךְ תְּחוֹת יַרְכִּי:
@23 וַאֲקַיֵּם עֲלָךְ בְּמֵימְרָא דַּיְיָ אֱלָהָא דִּשְׁמַיָּא וֵאלָהָא דְאַרְעָא דְּלָא תִסַּב אִתְּתָא לִבְרִי מִבְּנַת כְּנַעֲנָאֵי דִּי אֲנָא יָתֵב בֵּינֵיהוֹן:
@24 אֱלָהֵין לְאַרְעִי וּלְיַלָּדוּתִי תֵּיזִיל וְתִסַּב אִתְּתָא לִבְרִי לְיִצְחָק:
@25 וַאֲמַר לֵהּ עַבְדָא מָאִים לָא תֵיבֵי אִתְּתָא לְמֵיתֵי בַתְרַי לְאַרְעָא הָדָא הַאֲתָבָא אָתֵיב יָת בְּרָךְ לְאַרְעָא דִּי נְפַקְתָּא מִתַּמָּן:
@26 וַאֲמַר לֵהּ אַבְרָהָם אִסְתַּמַּר לָךְ דִּילְמָא תָתֵיב יָת בְּרִי לְתַמָּן:
@27 יְיָ אֱלָהָא דִּשְׁמַיָּא דִּי דַּבְּרַנִי מִבֵּית אַבָּא וּמֵאֲרַע יַלְדוּתִי וְדִי מַלֵּל לִי וְדִי קַיֵּם לִי לְמֵימַר לִבְרָךְ אֶתֵּן יָת אַרְעָא הָדָא הוּא יִשְׁלַח מַלְאָכֵהּ קֳדָמָךְ וְתִסַּב אִתְּתָא לִבְרִי מִתַּמָּן:
@28 וְאִם לָא תֵיבֵי אִתְּתָא לְמֵיתֵי בַתְרָךְ וּתְהֵי זַכָּאָה מִמּוֹמָתִי דָּא לְחוֹד יָת בְּרִי לָא תָתֵב לְתַמָּן:
@29 וְשַׁוִּי עַבְדָא יָת יְדֵהּ תְּחוֹת יַרְכָא דְאַבְרָהָם רִבּוֹנֵהּ וְקַיֵּם לֵהּ עַל פִּתְגָּמָא הָדֵין:
@30 וּדְבַר עַבְדָא עַשְׂרָא גַּמְלִין מִגַּמְלֵי רִבּוֹנֵהּ וַאֲזַל וְכָל שְׁפַר רִבּוֹנֵהּ בִּידֵהּ וְקָם וַאֲזַל לַאֲרָם דִּי עַל פְּרַת לְקַרְתָּא דְנָחוֹר:
@31 וְאַשְׁרֵי גַּמְלַיָּא מִבָּרָא לְקַרְתָּא לִבְאֵרָא דְמַיָּא לְעִדַּן רַמְשָׁא לְעִדַּן דְּנַפְקַן מַלְיָתָא:
@32 וַאֲמַר יְיָ אֱלָהֵהּ דְּרִבּוֹנִי אַבְרָהָם זַמִּין כְּעַן קֳדָמַי יוֹמָא דֵּין וְעִבַד טִיבוּ עִם רִבּוֹנִי אַבְרָהָם:
@33 הָא אֲנָא קָאֵם עַל עֵינָא דְמַיָּא וּבְנַת אֱנָשֵׁי קַרְתָּא נַפְקַן לְמִמְלֵי מַיָּא:
@34 וּתְהֵי עוּלֶמְתָּא דְּאֵימַר לַהּ אַרְכִינִי כְעַן קוּלְתִיךְ וְאֶשְׁתִּי וְתֵימַר אֵשְׁתְּ וְאַף גַּמְלָךְ אַשְׁקֵי יָתַהּ זַמִּנְתָּא לְעבְדָּךְ לְיִצְחָק וּבַהּ אִידַע אֲרֵי עֲבַדְתָּ טִיבוּ עִם רִבּוֹנִי:
@35 וַהֲוָה הוּא עַד לָא שֵׁיצֵי לְמַלָּלָא וְהָא רִבְקָה נְפָקַת דְּאִתְיְלִידַת לִבְתוּאֵל בַּר מִלְכָּה אִתַּת נָחוֹר אֲחוּהִי דְאַבְרָהָם וְקוּלְתַהּ עַל כַּתְפַּהּ:
@36 וְעוּלֶמְתָּא שַׁפִּירַת חֵיזוּ (נ''י שַׁפִּירָא לְמֶחֱזֵי) לַחֲדָא בְּתֻלְתָּא וּגְבַר לָא יַדְעָהּ וּנְחָתַת לְעֵינָא וּמְלַת קוּלְתַהּ וּסְלֵקָת:
@37 וּרְהַט עַבְדָּא לִקְדָמוּתַהּ וַאֲמַר אַשְׁקִינִי (נ''י אַטְעֵמְנִי) כְעַן זְעֵיר מַיָּא מִקּוּלְתִיךְ:
@38 וַאֲמֶרֶת אֵשְׁתְּ רִבּוֹנִי וְאוֹחִיאַת וַאֲחֵיתַת קוּלְתַהּ עַל יְדַהּ וְאַשְׁקְתֵהּ:
@39 וְשֵׁיצִיאַת לְאַשְׁקָיוּתֵהּ וַאֲמֶרֶת אַף לְגַמְלָךְ אַמְלֵי עַד דִּי סַפְקוּן לְמִשְׁתֵּי:
@40 וְאוֹחִיאַת וּנְפָצַת קוּלְתַהּ לְבֵית שַׁקְיָא וּרְהָטַת עוֹד לְבֵירָא לְמִמְלֵי וּמְלַת לְכָל גַּמְלוֹהִי:
@41 וְגַבְרָא שָׁהֵי בַהּ מִסְתַּכֵּל שָׁתִיק לְמֵידַע הַאַצְלַח יְיָ אָרְחֵהּ אִם לָא:
@42 וַהֲוָה כַּד סַפִּיקוּ גַּמְלַיָּא לְמִשְׁתֵּי וּנְסֵיב גַּבְרָא קָדָשָׁא דְדַהֲבָא תִּקְלָא מַתְקְלֵהּ וּתְרֵין שֵׁירִין עַל יְדָהָא מַתְקַל עֲשַׂר סִלְעִין דְּדַהֲבָא מַתְקַלְהוֹן:
@43 וַאֲמַר בַּת מָן אַתְּ חַוִּי כְעַן לִי הַאִית בֵּית אָבוּךְ אָתַר כָּשַׁר לָנָא לִמְבָת:
@44 וַאֲמֶרֶת לֵהּ בַּת בְּתוּאֵל אֲנָא בַּר מִלְכָּה דִּילֵידַת לְנָחוֹר:
@45 וַאֲמֶרֶת לֵהּ אַף תִּבְנָא אַף כִּסָּתָא סַגִּי עִמָּנָא אַף אָתַר כָּשַׁר לִמְבָת:
@46 וּכְרַע גַּבְרָא וּסְגִיד קֳדָם יְיָ:
@47 וַאֲמַר בְּרִיךְ יְיָ אֱלָהָא דְרִבּוֹנִי אַבְרָהָם דִּי לָא מְנַע טִיבוּתֵהּ וְקוּשְׁטֵהּ מִן רִבּוֹנִי אֲנָא בְּאוֹרַח תַּקְנָא דַּבְּרַנִּי יְיָ בֵּית אֲחוֹהִי דְרִבּוֹנִי:
@48 וּרְהָטַת עוּלֶמְתָּא וְחַוִּיאַת לְבֵית אִמַּהּ כְּפִתְגָּמַיָּא הָאִלֵּין:
@49 וּלְרִבְקָה אָחָא וּשְׁמֵהּ לָבָן וּרְהַט לָבָן לְוַת גַּבְרָא לְבָרָא לְוַת עֵינָא:
@50 וַהֲוָה כַּד חָזָא יָת קָדָשָׁא וְיָת שֵׁירַיָּא עַל יְדֵי אֲחָתֵהּ וְכַד שְׁמַע יָת פִּתְגָּמֵי רִבְקָה אֲחָתֵהּ לְמֵימַר כְּדֵין מַלֵּיל עִמִּי גַּבְרָא וַאֲתָא לְוַת גַּבְרָא וְהָא קָאֵם עִלַּוֵּי גַּמְלַיָּא עַל עֵינָא:
@51 וַאֲמַר עוּל בְּרִיכָא דַּיְיָ לְמָא אַתְּ קָאֵם בְּבָרָא וַאֲנָא פַּנֵּיתִי בֵיתָא וַאֲתַר כָּשַׁר לְגַמְלַיָּא:
@52 וְעַל גַּבְרָא לְבֵיתָא וּשְׁרָא גַּמְלַיָּא וִיהַב תִּבְנָא וְכִסָּתָא לְגַמְלַיָּא וּמַיָּא לְאַסְחָאָה רַגְלוֹהִי וְרַגְלֵי גֻּבְרַיָּא דְּעִמֵּהּ:
@53 וְשַׁוִּיאוּ קֳדָמוֹהִי לְמֵיכָל וַאֲמַר לָא אֵיכוּל עַד דַּאֲמַלֵּל פִּתְגָּמָי וַאֲמַר מַלֵּיל:
@54 וַאֲמַר עַבְדָּא דְאַבְרָהָם אֲנָא:
@55 וַיְיָ בְּרִיךְ יָת רִבּוֹנִי לַחֲדָא וּרְבָא וִיהַב לֵהּ עָאן וְתוֹרִין וּכְסַף וּדְהַב וְעַבְדִּין וְאַמְהָן וְגַמְלִין וְחַמָרִין:
@56 וִילֵידַת שָׂרָה אִתַּת רִבּוֹנִי בַר לְרִבּוֹנִי בָּתַר דְּסֵיבָת וִיהַב לֵהּ יָת כָּל דִּילֵהּ:
@57 וְקַיֵּם עָלַי רִבּוֹנִי לְמֵימָר לָא תִסַבּ אִתְּתָא לִבְרִי מִבְּנַת כְּנַעֲנָאֵי דִי אֲנָא יָתֵב בְּאַרְעֵהּ:
@58 אֶלָהֵן לְבֵית אַבָּא תֵּזִיל וּלְזַרְעִיתִי וְתִסַּב אִתְּתָא לִבְרִי:
@59 וַאֲמָרִית לְרִבּוֹנִי מָאִים לָא תֵיתֵי אִתְּתָא בַּתְרָי:
@60 וַאֲמַר לִי יְיָ דִּי פְלָחִית קֳדָמוֹהִי יִשְׁלַח מַלְאָכֵהּ עִמָּךְ וְיַצְלַח אָרְחָךְ וְתִסַּב אִתְּתָא לִבְרִי מִזְּרְעִיתִי וּמִבֵּית אַבָּא:
@61 בְּכֵן תְּהֵי זַכַּי (נ''י זַכָּא) מִמּוּמָתִי אֲרֵי תְהַךְ לְזַרְעִיתִי וְאִם לָא יִתְּנוּן לָךְ וּתְהֵי זַכַּי מִמּוּמָתִי:
@62 וְאָתִית (נ''י וַאֲתֵיתִי) יוֹמָא דֵּין לְעֵינָא וַאֲמָרִית יְיָ אֱלָהָא דְּרִבּוֹנִי אַבְרָהָם אִם אִית כְּעַן רַעֲוָא קֳדָמָךְ לְאַצְלָחָא אָרְחִי דִּי אֲנָא אָזֵיל עֲלַהּ:
@63 הָא אֲנָא קָאֵם עַל עֵינָא דְמַיָּא וִיהֵי עוּלֶמְתָּא דְּתִפּוֹק לְמִמְלֵי וְאֵימַר לַהּ אַשְׁקִינִי כְעַן זְעֵיר מַיָּא מִקּוּלְתִיךְ:
@64 וְתֵימַר לִי אַף אַתְּ אֵשְׁתְּ וְאַף לְגַמְלָיךְ אַמְלִי הִיא אִתְּתָא דְּזַמִּין יְיָ לְבַר רִבּוֹנִי:
@65 אֲנָא עַד לָא שֵׁיצִיתִי לְמַלָּלָא בְלִבִּי וְהָא רִבְקָה נְפָקַת וְקוּלְתַהּ עַל כַּתְפַּהּ וּנְחָתַת לְעֵינָא וּמְלָת וַאֲמָרִית לַהּ אַשְׁקִינִי כְעָן:
@66 וְאוֹחִיאַת וַאֲחִיתַת קוּלְתַהּ מִנַּהּ וַאֲמֶרֶת אֵשְׁתְּ וְאַף גַּמְלָךְ אַשְׁקִי וּשְׁתֵיתִי וְאַף גַּמְלַיָּא אַשְׁקִיאַת:
@67 וּשְׁאֵילִית יָתַהּ וַאֲמָרִית בַּת מָן אַתְּ וַאֲמֶרֶת בַּת בְּתוּאֵל בַּר נָחוֹר דִּילֵידַת לֵהּ מִלְכָּה וְשַׁוֵּיתִי קָדָשָׁא עַל אַפַּהּ וְשִׁירַיָּא עַל יְדָהָא:
@68 וּכְרָעִית וּסְגָדִית קֳדָם יְיָ וּבָרֵכִית יָת יְיָ אֱלָהֵהּ דְּרִבּוֹנִי אַבְרָהָם דְּדַבְּרַנִּי בְּאוֹרַח קְשׁוֹט לְמִיסַב יָת בַּת אֲחוּהִי דְּרִבּוֹנִי לִבְרֵהּ:
@69 וּכְעַן אִם אִיתֵיכוֹן עָבְדִין טִיבוּ וּקְשׁוֹט עִם רִבּוֹנִי חַוּוֹ לִי וְאִם לָא חַוּוֹ לִי וְאִתְפְּנֵי עַל יַמִּינָא אוֹ עַל שְׂמָאלָא:
@70 וְאָתֵיב לָבָן וּבְתוּאֵל וַאֲמָרוּ מִן קֳדָם יְיָ נְפַק פִּתְגָּמָא לֵית אֲנַחְנָא יָכְלִין לְמַלָּלָא עִמָּךְ בִּישׁ אוֹ טָב:
@71 הָא רִבְקָה קֳדָמָךְ דְּבַר וְאֵיזִיל וּתְהֵי אִתְּתָא לְבַר רִבּוֹנָךְ כְּמָא דִּי מַלֵּל יְיָ:
@72 וַהֲוָה כַּד שְׁמַע עַבְדָּא דְאַבְרָהָם יָת פִּתְגָּמֵיהוֹן וּסְגֵד עַל אַרְעָא קֳדָם יְיָ:
@73 וְאַפֵּק עַבְדָּא מָנִין דִּכְסַף וּמָנִין דִּדְהַב וּלְבוּשִׁין וִיהַב לְרִבְקָה וּמִגְדָּנִין יְהַב לַאֲחוּהָא וּלְאִמַּהּ:
@74 וַאֲכָלוּ וּשְׁתִיאוּ הוּא וְגוּבְרַיָּא דִּי עִמֵּהּ וּבָתוּ וְקָמוּ בְצַפְרָא וַאֲמַר שַׁלְּחוּנִי לְוַת רִבּוֹנִי:
@75 וַאֲמַר אֲחוּהָ וְאִמַּהּ תָּתֵיב עוּלֶמְתָּא עִמָּנָא עִדַּן בְּעִדַּן אוֹ עַשְׂרָא יַרְחִין בָּתַר כֵּן תֵּיזִיל:
@76 וַאֲמַר לְהוֹן לָא תְאַחֲרוּן יָתִי וַיְיָ אַצְלַח אָרְחִי שַׁלְּחוּנִי וְאֵיהַךְ לְוַת רִבּוֹנִי:
@77 וַאֲמַרוּ נִקְרֵי לְעוּלֶמְתָּא וְנִשְׁמָע מַה דְּהִיא אָמְרָה:
@78 וּקְרוֹ לְרִבְקָה וַאֲמַרוּ לַהּ הֲתֵיזְלִי עִם גַּבְרָא הָדֵין וַאֲמֶרֶת אֵיזִיל:
@79 וְשַׁלָּחוּ יָת רִבְקָה אֲחַתְהוֹן וְיָת מֵנִקְתַּהּ וְיָת עַבְדָּא דְאַבְרָהָם וְיָת גַּבְרוֹהִי:
@80 וּבָרִיכוּ יָת רִבְקָה וַאֲמַרוּ לַהּ אֲחָתָנָא אַתְּ הֲוֵי לְאַלְפִין וּלְרִבְוָן וְיִרְתוּן בְּנַיְכִי יָת קִרְוֵי סַנְאֵיהוֹן:
@81 וְקָמַת רִבְקָה וְעוּלֶמְתָּהָא וּרְכִיבָא עַל גַּמְלַיָּא וְאָזְלָּא בָּתַר גַּבְרָא וּדְבַר עַבְדָּא יָת רִבְקָה וַאֲזָל:
@82 וְיִצְחָק אָתָא מִמֵּתוֹהִי (נ''י עַל בְּמֵיתוֹהִי) מִבֵּירָא דְמַלְאָךְ קַיָּמָא אִתְחֲזֵי עֲלַהּ וְהוּא יָתֵב בַּאֲרַע דָּרוֹמָא:
@83 וּנְפַק יִצְחָק לְצַלָּאָה בְחַקְלָא לְמִפְנֵי רַמְשָׁא וּזְקַף עֵינוֹהִי וַחֲזָא וְהָא גַּמְלַיָּא אָתָן:
@84 וּזְקָפַת רִבְקָה יָת עֵינָהָא וַחֲזַת יָת יִצְחָק וְאִתְרְכִינַת מֵעַל גַּמְלָא:
@85 וַאֲמֶרֶת לְעַבְדָּא מָן גַּבְרָא דֵיכִי דִּמְהַלֵּךְ בְּחַקְלָא לְקַדָּמוּתָנָא וַאֲמַר עַבְדָּא הוּא רִבּוֹנִי וּנְסֵיבַת עֵיפָא וְאִתְכַּסִּיאַת:
@86 וְאִשְׁתָּעֵי עַבְדָּא לְיִצְחָק יָת כָּל פִּתְגָּמַיָּא דִּי עֲבָד:
@87 וְאַעֲלַהּ יִצְחָק לְמַשְׁכְּנָא וַחֲזָא וְהָא תַקְּנִין עוֹבָדָהָא כְּעוֹבָדֵי שָׂרָה אִמֵּהּ וּנְסֵיב יָת רִבְקָה וַהֲוַת לֵהּ לְאִנְּתּוּ וּרְחִימַהּ וְאִתְנְחֵם יִצְחָק בָּתַר דְּמִיתַת אִמֵּהּ:
@88 וְאוֹסֵיף אַבְרָהָם וּנְסֵיב אִתְּתָא וּשְׁמַהּ קְטּוּרָה:
@89 וִילֵידַת לֵהּ יָת זִמְרָן וְיָת יָקְשָׁן וְיָת מְדָן וְיָת מִדְיָן וְיָת יִשְׁבָּק וְיָת שׁוּחַ:
@90 וְיָקְשָׁן אוֹלִיד יָת שְׁבָא וְיָת דְּדָן וּבְנֵי דְדָן הֲווֹ לְמַשִּׁירְיָן וְלִשְׁכוּנִין וּלְּנַגְוָן:
@91 וּבְנֵי מִדְיָן עֵיפָה וָעֵפֶר וַחֲנוֹךְ וַאֲבִידָע וְאֶלְדָּעָה כָּל אִלֵּין בְּנֵי קְטוּרָה:
@92 וִיהַב אַבְרָהָם יָת כָּל דִּילֵהּ לְיִצְחָק:
@93 וְלִבְנֵי לְחֵינָתָא דִּי לְאַבְרָהָם יְהַב אַבְרָהָם מַתְּנָן וְשַׁלְחִנּוּן מֵעַל יִצְחָק בְּרֵהּ בְּעוֹד דְּהוּא קַיָּם קִידוּמָא לַאֲרַע מַדִינְחָא:
@94 וְאִלֵּין יוֹמֵי שְׁנֵי חַיֵּי אַבְרָהָם דַּחֲיָא מְאָה וְשַׁבְעִין וְחָמֵשׁ שְׁנִין:
@95 וְאִתְנְגִיד וּמִית אַבְרָהָם בְּסִיבוּ טָבָא סִיב וּשְׂבַע יוֹמִין וְאִתְכְּנִישׁ לְעַמֵּהּ:
@96 וּקְבָרוּ יָתֵהּ יִצְחָק וְיִשְׁמָעֵאל בְּנוֹהִי בִּמְעָרַת כָּפֶלְתָּא בַּחֲקַל עֶפְרוֹן בַּר צֹחַר חִתָּאָה דִּי עַל אַפֵּי מַמְרֵא:
@97 חַקְלָא דִּי זְבַן אַבְרָהָם מִן בְּנֵי חִתָּאָה תַּמָּן אִתְקְבַר אַבְרָהָם וְשָׂרָה אִתְּתֵהּ:
@98 וַהֲוָה בָּתַר דְּמִית אַבְרָהָם וּבָרֵךְ יְיָ יָת יִצְחָק בְּרֵהּ וִיתֵב יִצְחָק עִם בֵּירָא דְמַלְאָךְ קַיָּמָא אִתְחֲזֵי עֲלַהּ:
@99 וְאִלֵּין תּוּלְדַת יִשְׁמָעֵאל בַּר אַבְרָהָם דִּי יְלֵידַת הָגָר מִצְרֵתָא אַמְתָא דְשָׂרָה לְאַבְרָהָם:
@100 וְאִלֵּין שְׁמָהַת בְּנֵי יִשְׁמָעֵאל בִּשְׁמָהַתְהוֹן לְתוּלְדַתְהוֹן בּוּכְרָא דְיִשְׁמָעֵאל נְבָיוֹת וְקֵדָר וְאַדְבְּאֵל וּמִבְשָׂם:
@101 וּמִשְׁמָע וְדוּמָה וּמַשָּׂא:
@102 חֲדַד וְתֵימָא יְטוּר נָפִישׁ וָקֵדְמָה:
@103 אִלֵּין אִנּוּן בְּנֵי יִשְׁמָעֵאל וְאִלֵּין שְׁמָהַתְהוֹן בְּפַצְחֵיהוֹן וּבִכְרַכֵּיהוֹן תְּרֵין עֲסַר רַבְרְבִין לְאֻמֵּיהוֹן:
@104 וְאִלֵּין שְׁנֵי חַיֵּי יִשְׁמָעֵאל מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין וְאִתְנְגִיד וּמִית וְאִתְכְּנִישׁ לְעַמֵּהּ:
@105 וּשְׁרוֹ מֵחֲוִילָה עַד חַגְרָא דִּי עַל אַפֵּי מִצְרַיִם מָטֵי לְאָתוּר עַל אַפֵּי כָל אֲחוֹהִי שְׁרָא: פפפ:

@1 **ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים.** לכך נכתב שנה בכל כלל וכלל, לומר לך שכל אחד נדרש לעצמו, בת מאה כבת עשרים לחטא, מה בת עשרים לא חטאה, שהרי אינה בת ענשין, אף בת מאה בלא חטא, ובת עשרים כבת שבע ליופי: **שני חיי שרה.** כלן שוין לטובה:
@2 **בקרית ארבע.** על שם ארבע ענקים שהיו שם אחימן ששי ותלמי ואביהם. דבר אחר על שם ארבעה זוגות שנקברו שם איש ואשתו אדם וחוה, אברהם ושרה, יצחק ורבקה, יעקב ולאה: **ויבא אברהם.** מבאר שבע: **לספוד לשרה ולבכתה.** ונסמכה מיתת שרה לעקידת יצחק, לפי שעל ידי בשורת העקידה שנזדמן בנה לשחיטה וכמעט שלא נשחט, פרחה נשמתה ממנה ומתה:
@4 **גר ותושב אנכי עמכם.** גר מארץ אחרת ונתישבתי עמכם. ומדרש אגדה אם תרצו הריני גר, ואם לאו אהיה תושב ואטלנה מן הדין שאמר לי הקדוש ברוך הוא (לעיל יב ז) לזרעך אתן את הארץ הזאת: **אחזת קבר.** אחוזת קרקע לבית הקברות:
@6 **לא יכלה.** לא ימנע, כמו (תהלים מ יב) לא תכלא רחמיך, וכמו (לעיל ח ב) ויכלא הגשם:
@8 **נפשכם.** רצונכם: **ופגעו לי.** לשון בקשה, כמו (רות א טז) אל תפגעי בי:
@9 **המכפלה.** בית ועליה על גביו. דבר אחר שכפולה בזוגות: **בכסף מלא.** אשלם כל שויה, וכן דוד אמר לארונה (דברי הימים א' כא כד) בכסף מלא:
@10 **ועפרון ישב.** כתיב חסר, אותו היום מנוהו שוטר עליהם, מפני חשיבותו של אברהם שהיה צריך לו עלה לגדלה: **לכל באי שער עירו.** שכלן בטלו ממלאכתן ובאו לגמול חסד לשרה:
@11 **לא אדני.** לא תקנה אותה בדמים: **נתתי לך.** הרי הוא כמו שנתתיה לך:
@13 **אך אם אתה לו שמעני.** אתה אומר לי לשמוע לך ולקח בחנם, אני אי אפשי בכך, אך אם אתה לו שמעני הלואי ותשמעני: **נתתי.** דונא''י בלע''ז [נתתי] מוכן הוא אצלי והלואי נתתי לך כבר:
@15 **ביני ובינך.** בין שני אוהבים כמונו מה היא חשובה לכלום, אלא הנח את המכר ואת מתך קבור:
@16 **וישקל אברהם לעפרן.** חסר וי''ו, לפי שאמר הרבה ואפלו מעט לא עשה, שנטל ממנו שקלים גדולים שהן קנטרין, שנאמר (פסוק טז) עבר לסוחר, שמתקבלים בשקל בכל מקום ויש מקום ששקליהן גדולים שהן קנטרין, צינטינייר''ש [מטבעות של מאה] בלע''ז :
@17 **ויקם שדה עפרון.** תקומה היתה לה שיצאה מיד הדיוט ליד מלך. ופשוטו של מקרא ויקם השדה והמערה אשר בו וכל העץ לאברהם למקנה וגו':
@18 **בכל באי שער עירו.** בקרב כלם ובמעמד כלם הקנהו לו:
@21 **ברך את אברהם בכל.** בכל עולה בגימטריא בן, ומאחר שהיה לו בן היה צריך להשיאו אשה:
@22 **זקן ביתו.** לפי שהוא דבוק נקוד זקן: **תחת ירכי.** לפי שהנשבע צריך שיטול בידו חפץ של מצוה, כגון ספר תורה או תפלין, והמילה היתה מצוה ראשונה לו ובאה לו על ידי צער והיתה חביבה עליו ונטלה:
@27 **ה' אלהי השמים אשר לקחני מבית אבי.** ולא אמר ואלהי הארץ, ולמעלה אמר (פסוק ג) ואשביעך בה' אלהי השמים ואלהי הארץ. אמר לו עכשיו הוא אלהי השמים ואלהי הארץ, שהרגלתיו בפי הבריות, אבל כשלקחני מבית אבי היה אלהי השמים ולא אלהי הארץ, שלא היו באי עולם מכירים בו, ושמו לא היה רגיל בארץ: **מבית אבי.** מחרן: **ומארץ מולדתי.** מאור כשדים: **ואשר דבר לי.** לצרכי, כמו (מל''א ב ד) אשר דבר עלי, וכן כל לי ולו ולהם הסמוכים אצל דבור מפורשים בלשון על, ותרגום שלהם עלי עלוהי עליהון, שאין נופל אצל דבור לשון לי ולו ולהם, אלא אלי אליו אליהם ותרגום שלהם עמי עמיה עמהון, אבל אצל אמירה נופל לשון לי ולו ולהם: **ואשר נשבע לי.** בין הבתרים:
@28 **ונקית משבועתי** וגו' **.** וקח לו אשה מבנות ענר אשכול וממרא: **רק את בני** וגו' **.** רק, מעוט הוא. בני אינו חוזר, אבל יעקב בן בני, סופו לחזור:
@30 **מגמלי אדניו.** נכרין היו משאר גמלים, שהיו יוצאין זמומין מפני הגזל שלא ירעו בשדות אחרים: **וכל טוב אדניו בידו.** שטר מתנה כתב ליצחק על כל אשר לו, כדי שיקפצו לשלוח לו בתם: **ארם נהרים.** בין שתי נהרות יושבת:
@31 **ויברך הגמלים.** הרביצם:
@34 **אתה הכחת.** ראויה היא לו שתהא גומלת חסדים וכדאי לכנס בביתו של אברהם. ולשון הוכחת בררת, אפרוביש''ט בלע''ז : **ובה אדע.** לשון תחנה, הודע לי בה: **כי עשית חסד.** אם תהיה ממשפחתו והוגנת לו, אדע כי עשית חסד:
@36 **בתולה.** ממקום בתולים: **ואיש לא ידעה.** שלא כדרכה, לפי שבנות הגוים היו משמרות מקום בתוליהן ומפקירות עצמן ממקום אחר, העיד על זו שנקיה מכל:
@37 **וירץ העבד לקראתה.** לפי שראה שעלו המים לקראתה: **הגמיאיני נא.** לשון גמיעה, הומיי''ר בלע''ז :
@38 **ותרד כדה.** מעל שכמה:
@39 **עד אם כלו.** הרי אם משמש בלשון אשר, אם כלו, דיספקון, שזו היא גמר שתיתן כששתו די ספוקן:
@40 **ותער.** לשון נפיצה, והרבה יש בלשון משנה (עבודה זרה ה ז) המערה מכלי אל כלי, ובמקרא יש לו דומה (תהלים קמא ח) אל תער נפשי, (ישעיה נג יב) אשר הערה למות נפשו: **השקת.** אבן חלולה ששותים בה הגמלים:
@41 **משתאה.** לשון שאיה, כמו (ישעיה ו יא) שאו ערים, תשאה שממה: **משתאה.** משתומם ומתבהל על שראה דברו קרוב להצליח. אבל אינו יודע אם ממשפחת אברהם היא אם לאו. ואל תתמה בתי''ו של משתאה שאין לך תיבה שתחלת יסודה שי''ן ומדברת בלשון מתפעל שאין תי''ו מפרידה בין שתי אותיות של עיקר היסוד כגון משתאה מגזרת שאה, (ישעיה נט טו) משתולל מגזרת שולל, (שם נט טו) וישתומם מגזרת שממה, (מיכה ו טז) וישתמר חקות עמרי מגזרת וישמר, אף כאן משתאה מגזרת תשאה, וכשם שאתה מוצא לשון משומם באדם נבהל ונאלם ובעל מחשבות, כמו (איוב יח כ) על יומו נשמו אחרונים, (ירמיה ב יב) שמו שמים, (דניאל ד טז) אשתומם כשעה חדא, כך תפרש לשון שאיה באדם בהול ובעל מחשבות. ואונקלוס תרגם לשון שהיה וגוברא שהי, שוהא ועומד במקום אחד לראות ההצליח ה' דרכו. ואין לתרגם שתי, שהרי אינו לשון שתיה, שאין אל''ף נופלת בלשון שתיה: **משתאה לה.** משתומם עליה כמו (לעיל כ יג) אמרי לי אחי הוא, וכמו (לקמן כו ז) וישאלו אנשי המקום לאשתו:
@42 **בקע.** רמז לשקלי ישראל בקע לגלגלת: **ושני צמידים.** רמז לשני לוחות מצמדות: **עשרה זהב משקלם.** רמז לעשרת הדברות שבהן:
@43 **ויאמר בת מי את.** לאחר שנתן לה שאלה, לפי שהיה בטוח בזכותו של אברהם שהצליח הקדוש ברוך הוא דרכו: **ללין.** לינה אחת. לין שם דבר והיא אמרה ללון כמה לינות:
@44 **בת בתואל.** השיבתו על ראשון ראשון ועל אחרון אחרון:
@45 **מספוא.** כל מאכל הגמלים קרוי מספוא כגון תבן ושעורים:
@47 **בדרך.** דרך המימן, דרך הישר, באותו דרך שהייתי צריך. וכן כל בי''ת ולמ''ד וה''א המשמשים בראש התבה ונקודים בפת''ח מדברים בדבר הפשוט שנזכר כבר במקום אחר או שהוא מבורר וניכר באיזו הוא מדבר:
@48 **לבית אמה.** דרך הנשים היתה להיות להן בית לישב בו למלאכתן, ואין הבת מגדת אלא לאמה:
@49 **וירץ.** למה וירץ ועל מה רץ, ויהי כראות את הנזם, אמר עשיר הוא זה, ונתן עיניו בממון:
@50 **על הגמלים.** לשמרן, כמו (לעיל יח ח) והוא עומד עליהם, לשמשם:
@51 **פניתי הבית.** מעבודה זרה:
@52 **ויפתח.** התיר זמם שלהם, שהיה סותם את פיהם שלא ירעו בדרך בשדות אחרים:
@53 **עד אם דברתי.** הרי אם משמש בלשון אשר ובלשון כי, כמו (לקמן מט י) עד כי יבא שילה, וזה שאמרו חכמינו זכרונם לברכה כי משמש בארבע לשונות, והאחת אי, והוא אם:
@56 **ויתן לו את כל אשר לו.** שטר מתנה הראה להם:
@57 **לא תקח אשה לבני מבנות הכנעני.** אם לא תלך תחלה אל בית אבי ולא תאבה ללכת אחריך:
@59 **אלי לא תלך האשה.** אלי כתיב, בת היתה לו לאליעזר והיה מחזר למצוא עלה שיאמר לו אברהם לפנות אליו להשיאו בתו, אמר לו אברהם בני ברוך ואתה ארור, ואין ארור מדבק בברוך:
@62 **ואבא היום.** היום יצאתי והיום באתי, מכאן שקפצה לו הארץ. אמר רבי אחא יפה שיחתן של עבדי אבות לפני המקום מתורתן של בנים, שהרי פרשה של אליעזר כפולה בתורה, והרבה גופי תורה לא נתנו אלא ברמיזה:
@64 **גם אתה.** גם לרבות אנשים שעמו: **הכיח.** ברר והודיע, וכן כל הוכחה שבמקרא ברור דבר:
@65 **טרם אכלה.** טרם שאני מכלה, וכן כל לשון הוה פעמים שהוא מדבר בלשון עבר ויכול לכתוב כמו טרם כליתי, ופעמים שמדבר בלשון עתיד, כמו (איוב א ה) כי אמר איוב, הרי לשון עבר, (שם) ככה יעשה איוב הרי לשון עתיד. ופירוש שניהם לשון הווה, כי אומר היה איוב (שם) אולי חטאו בני וגו' והיה עושה כך:
@67 **ואשאל ואשים.** שנה הסדר, שהרי הוא תחלה נתן ואחר כך שאל, אלא שלא יתפשוהו בדבריו ויאמרו היאך נתת לה, ועדיין אינך יודע מי היא:
@69 **על ימין.** מבנות ישמעאל: **על שמאל.** מבנות לוט שהיה יושב לשמאלו של אברהם:
@70 **ויען לבן ובתואל.** רשע היה וקפץ להשיב לפני אביו: **לא נוכל דבר אליך.** למאן בדבר הזה, לא על ידי תשובת דבר רע ולא על ידי תשובת דבר הגון לפי שנכר שמה' יצא הדבר, לפי דבריך שזמנה לך:
@72 **וישתחו ארצה.** מכאן שמודים על בשורה טובה:
@73 **ומגדנות.** לשון מגדים, שהביא עמו מיני פירות של ארץ ישראל:
@74 **וילינו.** כל לינה שבמקרא לינת לילה אחד:
@75 **ויאמר אחיה ואמה.** ובתואל היכן היה, הוא היה רוצה לעכב ובא מלאך והמיתו: **ימים.** שנה, כמו (ויקרא כה כט) ימים תהיה גאלתו, שכך נותנין לבתולה זמן שנים עשר חדש לפרנס את עצמה בתכשיטים: **או עשור.** עשרה חדשים. ואם תאמר ימים ממש, אין דרך המבקשים לבקש דבר מועט ואם לא תרצה תן לנו מרבה מזה:
@77 **ונשאלה את פיה.** מכאן שאין משיאין את האשה אלא מדעתה:
@78 **ותאמר אלך.** מעצמי, ואף אם אינכם רוצים:
@80 **את היי לאלפי רבבה.** את וזרעך תקבלו אותה ברכה שנאמר לאברהם בהר המוריה (לעיל כב יז) הרבה ארבה את זרעך וגו' . יהי רצון שיהא אותו הזרע ממך ולא מאשה אחרת:
@82 **מבוא באר לחי ראי.** שהלך להביא הגר לאברהם אביו שישאנה: **יושב בארץ הנגב.** קרוב לאותו באר, שנאמר (לעיל כ א) ויסע משם אברהם ארצה הנגב וישב בין קדש ובין שור, ושם היה הבאר, שנאמר (שם טז יד) הנה בין קדש ובין ברד:
@83 **לשוח.** לשון תפלה, כמו (תהלים קב א) ישפוך שיחו:
@84 **ותרא את יצחק.** ראתה אותו הדור ותוהא מפניו: **ותפל.** השמיטה עצמה לארץ, כתרגומו ואתרכינת הטתה עצמה לארץ ולא הגיעה עד הקרקע, כמו (פסוק יד) הטי נא כדך, ארכיני, (ש''ב כב י) ויט שמים, וארכין, לשון מטה לארץ, ודומה לו (תהלים לז כד) כי יפל לא יוטל, כלומר אם יטה לארץ לא יגיע עד הקרקע:
@85 **ותתכס.** לשון ותתפעל, כמו ותקבר, ותשבר:
@86 **ויספר העבד.** גלה לו נסים שנעשו לו שקפצה לו הארץ ושנזדמנה לו רבקה בתפלתו:
@87 **האהלה שרה אמו.** ויביאה האהלה ונעשית דגמת שרה אמו, כלומר והרי היא שרה אמו, שכל זמן ששרה קימת היה נר דלוק מערב שבת לערב שבת, וברכה מצויה בעיסה, וענן קשור על האהל, ומשמתה פסקו, וכשבאת רבקה חזרו: **אחרי אמו.** דרך ארץ כל זמן שאמו של אדם קימת כרוך הוא אצלה, ומשמתה הוא מתנחם באשתו:
@88 **קטורה.** זו הגר, ונקראת קטורה על שם שנאים מעשיה כקטרת ושקשרה פתחה שלא נזדוגה לאדם מיום שפרשה מאברהם:
@90 **אשורם ולטושם.** שם ראשי אומות. ותרגום של אנקלוס אין לי לישבו על לשון המקרא. שפרש למשרין, לשון מחנה. ואם תאמר שאינו כן מפני האל''ף שאינה יסודית, הרי לנו תבות שאין בראשם אל''ף ונתוספה אל''ף בראשם, כמו (עמוס ז ז) חומת אנך, שהוא מן (שמואל ב' ד ד) נכה רגלים, וכמו (מלכים ב' ד ב) אסוך שמן שהוא מן (רות ג ג) ורחצת וסכת: **ולטושם.** הם בעלי אהלים המתפזרים אנה ואנה ונוסעים איש באהלי אפדנו, וכן הוא אומר (ש''א ל טז) והנה נטושים על פני כל הארץ, שכן למ''ד ונו''ן מתחלפות זו בזו:
@92 **ויתן אברהם** וגו' **.** אמר ר' נחמיה ברכה דיאתיקי, שאמר לו הקדוש ברוך הוא לאברהם (לעיל יב ב) והיה ברכה, הברכות מסורות בידך לברך את מי שתרצה, ואברהם מסרם ליצחק:
@93 **הפילגשים.** חסר כתיב, שלא היתה אלא פלגש אחת, היא הגר היא קטורה. נשים בכתבה, פילגשים בלא כתבה, כדאמרינן בסנהדרין (כא א) בנשים ופילגשים דדוד: **נתן אברהם מתנת.** פרשו רבותינו שם טמאה מסר להם. דבר אחר מה שנתן לו על אודות שרה ושאר מתנות שנתנו לו, הכל נתן להם שלא רצה להנות מהם:
@94 **מאת שנה ושבעים שנה וחמש שנים.** בן מאה כבן שבעים, ובן שבעים כבן חמש בלא חטא:
@96 **יצחק וישמעאל.** מכאן שעשה ישמעאל תשובה והוליך את יצחק לפניו, והיא שיבה טובה שנאמר באברהם:
@98 **ויהי אחרי מות אברהם ויברך** וגו' **.** נחמו תנחומי אבלים. דבר אחר אף על פי שמסר הקדוש ברוך הוא את הברכות לאברהם, נתיירא לברך את יצחק מפני שצפה את עשו יוצא ממנו, אמר יבא בעל הברכות ויברך את אשר ייטב בעיניו ובא הקדוש ברוך הוא וברכו:
@100 **בשמתם לתולדתם.** סדר לידתן זה אחר זה:
@103 **בחצריהם.** כרכים שאין להם חומה, ותרגומו בפצחיהון, שהם מפוצחים לשון פתיחה, כמו (תהלים צח ד) פצחו ורננו:
@104 **ואלה שני חיי ישמעאל** וגו' **.** אמר רבי חייא בר אבא למה נמנו שנותיו של ישמעאל, כדי ליחס בהם שנותיו של יעקב. מן שנותיו של ישמעאל למדנו ששמש יעקב בבית עבר ארבע עשרה שנה כשפרש מאביו קודם שבא אצל לבן, שהרי כשפרש יעקב מאביו מת ישמעאל, שנאמר (להלן כח ט) וילך עשו אל ישמעאל וגו' , כמו שמפורש בסוף מגלה נקראת (מגילה יז א) : **ויגוע.** לא נאמרה גויעה אלא בצדיקים:
@105 **נפל.** שכן, כמו (שופטים ז יב) מדין ועמלק וכל בני קדם נופלים בעמק. כאן הוא אומר לשון נפילה, ולהלן הוא אומר על פני כל אחיו ישכן (לעיל טז יב) , עד שלא מת אברהם ישכן, משמת אברהם נפל:
@106 **ולא יחם לו.** אמרו רבותינו ( ברכות סב ב ): **כל המבזה בגדים, אינו נהנה מהם לסוף, לפי שקרע את כנף המעיל לשאול.** ומדרש אגדה: אמר רב שמואל בר נחמני: כשראה דוד את המלאך עומד בירושלים וחרבו בידו, נצטנן דמו מיראתו ( ראה פרקי דרבי אליעזר פרק מג ):
@107 **בתולה.** בתוליה מחממין את בשרה: **סוכנת.** מחממת, וכן ( קהלת י ט ): ובוקע עצים יסכן בם:
@109 **לא ידעה.** שהבתולה יפה לחמם מן הבעולה. ורבותינו אמרו ( סנהדרין כב א ) משום לא ירבה לו נשים ( דברים יז יז ), וכבר היו לו שמונה עשר ( רש"י שם ):
@110 **מתנשא.** מתפאר: **וחמשים איש.** נטולי טחול וחקוקי כפות רגלים ( שם כא ב ):
@111 **ולא עצבו.** לא הכעיסו, למדך שהמונע תוכחה מבנו, מביאו לידי מיתה: **וגם הוא טוב תואר.** כאבשלום, שנאמר ( שמואל ב יד כה ): וכאבשלום לא היה איש יפה, היא גרמה להם שנתגאו: **ואותו ילדה.** אמו: **אחרי אבשלום.** כלומר גדלתו אחר תרבות שגדלה אמו של אבשלום:
@112 **עם יואב בן צרויה.** לפי שהיה יודע שבלבו של דוד עליו, על שהרג את אבנר ועמשא ואבשלום, וסופו שיצוה את בנו המולך תחתיו עליו, לפיכך היה רוצה שימלוך זה על ידו, ויאהבנו: **ועם אביתר הכהן.** שנסתלק מן הכהונה משברח דוד מירושלים מפני אבשלום, ששאל באורים ותומים ולא עלתה לו, שנאמר ( שמואל ב טו כד ): ויעל אביתר, והיה מבני בניו של עלי, וידע שלא ישמש בימי שלמה, שהרי נאמר לעלי ( שמואל א ב לה ): והקימותי לי כהן נאמן והתהלך לפני משיחי, והיה חפץ שיעמוד זה על ידו:
@113 **ונתן הנביא.** שנבא לדוד ששלמה ימלוך; כמו שנאמר בדברי הימים ( א כב ט ): ושלמה יהיה שמו:
@114 **ומריא.** שור של פטם: **אבן הזוחלת.** אבן גדולה, שהיו הבחורים מנסין בה את כחם להזיזה ולגררה, לשון מים זוחלין, ( דברים לב כד ): **זוחלי עפר.** ויונתן תרגם: אבן סכותא, שעומדין עליה וצופין למרחוק: **עין רוגל.** תירגם יונתן: עין קצרא, הוא כובס, שמתקן בגדי צמר ברגליו, על ידי בעיטה:
@115 **ואת שלמה אחיו לא קרא.** שיודע היה, שהתנבא עליו הנביא למלוך:
@117 **ומלטי את נפשך.** מן המחלוקת לאחר מות המלך, שירצה בנך למלוך, כמה שהבטיחו הקדוש ברוך הוא:
@126 **חטאים.** חסרים ומנועין מן הגדולה כמו ( שופטים כ טז ): **אל השערה ולא יחטיא.** ( כד ) אתה אמרת. בתמיה ( כה ) כי ירד היום. שהעיר היתה: .**** גבוהה, ואבן הזוחלת למטה בגיא:

@4 **גר ותושב.** הוא הגר שבא להתישב במקום והוא גר תושב.
@6 **נשיא אלהים.** ר"ל גדול ונכבד בעיני אלהים.
@6 **לא יכלה.** לא ימנע.
@8 **את נפשכם.** את רצונכם.
@8 **ופגעו לי.** חלו פניו בעכורי.
@9 **המכפלה.** שהיתה כפולה וזה אם כשהיתה שם מערה על גבי מערה או מערה לפנים ממערה.
@9 **בכסף מלא.** בסף שלם ר"ל שימכרה לו כדי שוויה כי אינו מבקש לו חסד בזה.
@13 **אך אם אתה לו שמעני.** רוצה לומר אך אם אתה בזה הרצון שלא יכבד עליך עזבך זאת הנחלה כמו שנראה מדבריך מי יתן שתשמע לי אתן כסף השדה כמו שאמרתי קח אותו ממני. ואולם אמר זה כי דרך בני האדם לומר כמו אלו הדברים על צד ההמלט מהמחלי' פניהם לדעתם שלא יקחו בני האדם כמו זאת המתנה. ולזה לא היה יודע אברהם אם אמר זה עפרון על צד ההמלט או אמר זה לכונה טובה והנה קצר אברם מלבאר זה מאמר לעפרון לכבודו. או יהיה הרצון כזה אך אם אתה לו תהיה בזה הרצון שאת' מראה לי בדבריך הנני מחלה פניך שתשמעני אתן כסף השד' קח ממני והפירוש השני יותר נאות מהראשון.
@16 **עובר לסוחר.** רוצה לומר שהמטבע שנתן לו היה שלם ומתקבל לסוחר שהוא משוטט בארצו' לסחורתו לפי שהמטבע ההוא היה מתקבל בכל המקומות לחשיבותו ושלמותו. ולזה שקלו לו. או היה מה שנתן לו כסף לא מטבע ונתן לו כסף נקי שיקחהו כל סוחר. כי הסוחר הוא מכיר אי זי כסף הוא נקי יותר משאר האנשים.
@22 **תחת ירכו.** הנכון בו הוא כמו שפירש החכם ר"ע והוא שידמה שכבר היה מנהג בימים ההם לשים אדם ידו תחת ירך מי שהוא ברשותו והאדון יושב וירכו על היד להורות שידו תחת רשותו לעשות כרצונו וספר שזה המנהג היה בימיו בארץ הודו.
@23 אמר **אלהי השמים ואלהי הארץ** הנה אמר זה להורות שמנהיג אחד הוא מנהיג הכל והעיר גם כן שהשגחת ה' הוא בארץ.
@25 **ההשב אשיב.** אמר זה בעבור אברהם שיצא משם כמו שאמ' ודור רביעי ישובו הנה בעבור אברהם שיהיה גר בארץ כנען כי הדור היוצא ממצרים לא יצא מארץ כנען בדרך שיתכן שיאמר בו שישוב לארץ כנען.
@30 **וכל טוב אדוניו בידו.** ר"ל שהיה מטוב אדוניו הרבה בידיו והיה נושאים אותו העשרה גמלים כי בכמו אלו הדברים יאמר הכולל תמורת החלקי אמר וישכימו בבקר והנה כלם פגרים מתים. והרצון בו רובם שאם היו כלם מתים לא היו שם משכימים בבקר. ובכמו זה ימצאו רבים בכתוב'.
@36 **בתולה ואיש לא ידעה.** ר"ל שהיא בתולה ולא ידעה איש לשכב עמה כדרכה ושלא כדרכה. והנה תצא לשון ידיעה במשכב שלא כדרך. כאמרו הוציאם אלינו ונדעה אותם.
@39 **כלו לשתות.** השלימו לשתות.
@41 **משתאה לה.** משתומם בעבורה.
@41 **מחריש.** ר"ל שהיה שותק ולא היה מדבר לה דבר לראות אם תתעורר מעצמה לשאב לכל גמליו.
@43 **ויאמ' בת מי את.** וכבר אמר לה תחלה בת מי את קודם שיתן הנזם והצמידים. ואמנם זכר תחלה נתינתו לה והנזם והצמידים לסדר זה הסדור באופן השלם להורות שהו' נתן לה אלו התכשיטין על החסד שגמלה אותו ללין. אמרו בב"ר שהוא לינה אחת והיא השיבה לו ללון שהוא כמה לינות. ושמעתי בזה מאדני אבי ז"ל באור נאות מאד והוא כי ללין הוא מבנין הפעיל. והרצון בו אצלם שזולתו ילין אותו שם והדבר שהוא בזה התואר לק יקח האדם ממנו כי אם מעט וללון הוא מבנים פעל קל והרצון בו שיהיה לו ממשלה מעצמו ללון שם ולזה יקח אם ירצה כמה לינות. והנראה שאין הבדל בין ללין וללון כי ההפעיל הוא בודד גם כן מה שנמצא בכתוב אמר וילן שם כי בא השמש. צדק ילין בה.
@47 **חסדו ואמתו.** החסד הוא מה שייטיבו לאדם על צד החנינה. ואמת הוא. לתת לאדם החק שיש לו עליו. ומפני זה נקרא קיום החסד שיעד ה' לנביא אמת כי אחר יעוד ראוי שיקיימהו הש"י ולזה אמר תתן אמת ליעקב חסד לאברהם כי מה שהיה חסד לאברהם הוא אמת ליעקב.
@73 **ומגדנות נתן.** הם עניינים חמודים מאד אם בגדים או זולתם.
@75 **ימים.** שנה כמו ימים תהיה גאולתו ונקראת השנה בה השם לפי שהוא כמו יום אחד ארוך כמו שזכרנו בפרשת יהי מאורות.
@75 **עשור.** עשרה חדשים.
@83 **לשוח בשדה.** להתפלל והוא מעניין ולפי יי' ישפוך שיחו.
@83 **לפנות ערב.** סמוך לשקיעת החמה.
@84 **ותפל מעל הגמל.** ר"ל שירדה מעל הגמל בראותה יצחק כי אמר לה העבד שהוא יצחק.
@87 **האהלה שרה אמו.** האהל. אהל שרה אמו כמו והנבואה עורר הנביא.
@87 **אחרי אמו.** אחרי מות אמו.

@1 **ויהי חיי שרה מאה שנה וגומר. עד ואברהם זקן בא בימים ויי' ברך אברהם בכל.**
@1 **ביאור הספור:**
@1 **זכר** שחיי שרה היו קכ"ז שנה ושכבר מתה בקרית ד' בארץ כנען וכאשר ידע אברהם מיתתה בא לספוד לשרה ולבכותה. ואחר כן קם אברהם מעל פני הגוף המת והשתדל לקברו. ולזה דבר לבני חת שיתנו לו אחוזת קבר עמהם לקבור מתו. כי הוא. אם הוא גר בארץ ההיא הנה רצונו הוא להתיישב שם ולזה יצטרך לו שם אחוזת קבר ולה ענו אותו בני חת שיקבר מתו במבחר קבריהם כי לא ימנע איש את קברו ממנו. והנה נתן אברהם תודה על זה החסד לבני חת ואמר להם שהוא לא שאל מהם כך אבל שאל מהם שימכרו לו מקו' ראוי לאחוזת קבר. ולזה אמר להם שאם ייטב בעיניהם שיקברו מתו במבחר ארצם הנה הוא מחלה פניהם שיפגעו בעבורו בעפרון בן צהר וימכר לו בכסף מלא מערת המכפלה אשר בקצה שדהו לאחוזת קבר ועפרון היה שם ואמ' לאברהם שהוא נותן לו השדה והמערה אשר בו וידמה שכבר אמר לו זה להורות שהשדה לא ישוה. לו דבר אם תהיה המערה אחוזת קבר לאברהם ולזה לא נרצה למכור לו המער' לבדה כמו שהיה שואל אברהם. וכאשר הבין זה אברהם מדבריו נתן לו תודה על החסד שאמר לו ואמר אל עפרון אך אם אתה לו שמעני תהיה בזה הרצון אשר אתה מראה לי שלא יקשה בעיניך עזבך זאת הנחלה. שמעני אתן כסף השדה קח ממני ואקברה את מתי שמה רוצה לומ' במערת המכפלה אשר לו וענה אותו עפרון אדני שמעני ארץ ארבע מאות שקל כסף ביני ובינך מה היא קח אותה בלי כסף וקבור מתך. והנה אמר זה בזה האופן מהתחבולה כי הוא אמר לו תחלה שיתננה לו והשיב מפני זה לאמר בכמה יתננה לו ואמר מה שכחו כח המאמר ההוא כי הוא הודיעו בזה המאמר הערך שהוא מעריך השדה עם שכבר נמשך בזה המאמר שלא יבקש אברהם ממנו זה השדה בפחות מזה הסך כי הוא לא אמר לו שירצה למכרו לו. והנה הביא עפרון את אברהם בזה המאמר שיפרע בזה השדה יותר מכדי שוויו על צד התחבולה ויורה שכבר אמר זה עפרון כדי שיתן לו אברהם זהו הסך כי הוא לא מאן לקחת הכסף. והנה נתרצה אברהם במה שאמר עפרון ונתן לו ארבע מאות שקל כסף שלמי המשקל והיו מכסף נקי ונתקיים שדה עפרון והמערה אשר בו וכל העץ אשר בכל גבולו סביב לקניין לאברהם לעיני בני חת. והיו שם במעמד ההוא כל אנשי העיר וכולם הסכימו ונתנו רשות לאברהם שיקבר מתיו בשד הההיא והמערה אשר בו הוא והבאים אחריו. ולזה היה לאברהם זה השדה והמערה אשר בו לו לאחוזת קבר מאת בני חת. והתועלות המגיעים מזה הספור הם רבים:
@1 **התועת** הראשון הוא במדות. והוא שראוי לאדם לספוד ולבכות על קרוביו ושוכבת חקו כשמו כי בזה תועל להראות האדם אהבה לקרוביו באי זה האופן היא עד שהוא ראוי שיהיה דואג עליהם בהפקדם כאלו נאכל חצי בשרו והנה אהבת בני המשפחה קצתם לקצת הוא מה שיש לו מבא גדול בתיקון הקבוץ המדיני וכל שכן אהבת האדם ואשתו זה את זה עם שבזה הישרה להניע האדם בשישתדל ברפואתם כשיחלו כפי מה שאפר לו. ולזה תמצא שאברהם ספד לשרה ובכה עליה:
@21 **ואברהם זקן בא בימים וגומ' עד סוף הפרשה.**
@21 **ביאור הספור:**
@21 **זכר** שאברהם היה זקן בא ביים רבים וברכהו ה' בכל מיני הברכה ר"ל שהיה לו עושר וכבוד רב והצליח מאד בכל קניניו. והנה אמר אברהם אל עבדו שעמד בביתו ימים רבים וגדל עמו אשר השליטו אברהם על כל אשר לו שישים ידו תחת ירכו להורות שידו הוא ברשותו כמו שהיה המנהג בימים ההם וישבע לו ביי' אלהי השמים והארץ שלא יקח אשה לבנו יצחק מבנות הכנעני ואף על פי שהוא יושב בקרבו כי לא בחר בארץ ההיא מפני יושביה אבל מפני היותר מוכנת אל שידבק בה השפע האלהי למי שהוא מוכן לזה והנה מנהג הכנענים היה פחות מאד כמו שזכרנו במה שקדם. ועוד שכבר נתקלל כנען כמו שזכר בפרת נח. ולזה היה מרחיק אברהם ליצחק מהתחתן בכנענים כי בו בחר ה' להיות ממנו הזרע הנבחר כמו שקדם ומפני זה בחר לו אברהם מבנות ארצו ומהם בחר יותר בבנות משפחתו וצוה לעבדו שיקח ליצחק אשה משם ואם לא ימצא ממשפחתו יקח מארצו. והנה שאל ממנו העבד אם לא תאבה האשה ללכת אחרי לארץ כנען האם אשיב יצחק אל הארץ אשר יצאת משם אחר שאתה היית בוחר בבנות הארץ ההיא. והשיב לו אברהם השמר לך מהוציא בני מארץ כנען להשיבו שם ואל תירא שלא תאבה האשה ללכת אחריך כי השם יתעלה שהוציאני מבית אבי ונהג אותי בארץ הזאת אשר ייעד לי ונשבע לי שיתן לזרעי הארץ הזאת הוא יעזרך על זה כי זה הוא אחד מהכלי' אשר יתכן בהם שיתקיים יעוד השם לי שיירש זרעי הארץ הזאת כי בזה יהיה זרע יצחק יותר מוכן אל השלמות. והנה לא תאבה האשה ללכת אחריך ךהנך נקי משבועתך זאת אשר אני משביעך לקחת אשה לבני מארצי וממולדתי אבל השמר עכ"פ שלא תשב בני שמה. והנה שם העבד את ידו תחת ירך אברהם אדניו כאשר צוהו ונשבע לו על הדבר הזה ולקח העבד עשרה גמלים מגמלי אדניו וטען אותם מהיותר נבחר מקנייני אברהם כדי שידעו האנשים ההם עושר אברהם ויאותו להתחתן בו ואם הוא בארץ רחוקה מהם והלך אל ארם נהרים שהיה יושב בה נחור ובהגיעו שם הכריך הגמלים על ברכיהם כמנהגם מחוץ לעיר. אל באר המים. שיקחו ממנו מים אנשי העיר. ויהי זה לעת ערב. לעת שתצאנה השואבות לשאוב מים והתפלל העבד לשם יתעלה ואמר יי' אלהי אדני אברה' הכן לפני היום מה שאני מבקש ועשה חסד עם אדני אברהם שתכין לי נערה נבחרת במדותיה להיות לאשה לעבדך ליצחק כי היא ראויה לו כדי שיהיה לו ממנה זרע שלם. והנני בוחן אי זה מהנערות היא ראויה לו בזה האופן והוא שאני נצב על עין המים ובנות אנשי העיר יוצאות לשאוב מים והיה הנערה אשר אומ' אליה הטי נא כדך ואשתה והיא תתנדב מעצמה לטוב מוסרה להשקות אותי ולשאוב לגמלים הנה הנערה ההיא ראויה ליצחק ובה אדע כי עשית חסד עם אדני להכין לבנו אשה מארצו בעלת מדות חשובות אם אהיה נעזר מאתך שתלך האשה ההיא אחרי. והנה טרם כלה לדבר אל לבו והנה רבקה יוצאת שהיתה בת בתואל אשר הוא בן מלכה שהיתה בת אחי אברהם ובן נחור שהיה אחי אברהם והיה כדה על שכמה והנערה היתה יפה מאד בתולה ואיש לא ידעה אפילו שלא כדרכה וירדה אל העין ומלאת כדה ועלתה ורץ העבד לקראתה ואמר לה השקיני נא מעט מים מכדך והיא לטוב מוסרה ואף על פי שכבר החזיקה בדרך לשוב לביתה הסכימה להשקותו ושאבה בחריצו' גדול לכל גמליו והנה היה העבד משתומם בעבורה שלא רצה לדבר לה מאומה לדעת אם תעשה מעצמ' זה העניין שרצה לבחון בו הנערה הראויה ליצחק וראה אחר זה לדעת אם זאת הנערה היא ממשפחת אברהם כדי שישתדל בה תחלה כי זה היה רצון אברהם. רצוני שיקח מהיותר קרוב אליו ממשפחתו אם יוכל וזה מבואר ממה שצוהו לקחת אשה ממשפחתו ואם לא יוכל יקח מארצו וזה ממה שיראה ממנו שרצונו היה שישתדל מיותר קרוב לאברהם ראשונה. והנה כאשר כלו הגמלים לשתות לקח האיש נזם זהב היה משקלו שקל ושני צמידי' של זהב היה עשרה סלעים משקלם ונתן אותם לזאת הנערה אחר שידע בת מי היא. והנה שאל אותה בת מי את הגידי נא לי היש בין אביך מקום לנו ללין והיא השיבו לו על השאלה הראשונה שהיא בת בתואל בן מלכה אשר ילדה אותו לנחור ועל השאלה השנית השיבה גם תבן גם מספא רב עמם לאכול לגמלים גם מקום ללון. והנה כראות העבד כי הצליח השם דרכו ביותר שלם שבפנים נתן תודה לש"י והשתחוה לו ואמר ברוך יי' אלהי אדני אברהם שלא עזב חסדו ואמרתו מעם אדני. הנה אנכי בדרך הנבחר יותר נחני השם וזה שכבר נחני בית אחי אדני והנה הלכה הנערה והגידה לבית אמה כדברים האלה אשר דבר אליה עבד אברהם והראה אותה מה שנתן לה כי זה משפט הבנות להיות דבריהן עם אמן לא עם אביהן והיה זה סבה שידע זה אחיה לבן כל אלו הדברים ורץ אל האיש החוצה אל העין והביאו אל הבית הוא וגמליו ונתן תבן ומספא לגמלים ומים לרחוץ רגלי העבד ורגלי האנשים אשר אתו ושמו אנשי הבית לפניו לאכל ואמ' לא אוכל עד אשלי' לדבר דברי ויאמ' אליו גדול הבית אשר שם דבר ואמר להם שהוא עבד אברהם ושכבר נתן לו השם עושר רב וילדה לו שרה בן אחרי זקנתה ונתן לו אברהם כל אשר לו לאהבתו אותו ושכבר השביעהו אברהם שלא יקח אשה לבנו מבנות הכנעני אשר הוא יושב בארצו אך ילך אל בית אביו ולמשפחתו לקחת אשה לבנו משם והבטיחו שכבר יעזרהו השי"ת לקחת אשה לבנו משם תלך אחריו אל יצחק וספ' להם אח' זה כל מה שקרהו מעניי' מה שהסכי' עם לבו לבחון הנערה הראויה ליצחק ושכבר עתה רבקה זה העניין אשר שם בו זאת הבחינה ושאחרי שידע בת מי היא נתן לה הנזם והצמידים והודה לשם יתעלה על הטובה אשר גמלהו להדריכו בדרך היותר נכון שאפשר לעשות את בקשתו ואמר להם אחר זה אם ישכם עושים חסד ואמת עם אדני לתת רבקה לבו ותלך אחרי בארצו הגידו לי ואם לא הגידו לי ואראה אם אמצא אחר' ממשפחת אדוני אם מארצו אם לא אמצא משפחתו. ויען לבן ובתואל כי מיי' יצא דבר הזה לא נוכל לסרב בזה ואמרו לו הנה רבקה לפניך קח ולך. ותהי אשה ליצחק כאשר דבר השם יתעלה אשר מאתו נהיה זה הדבר והסכים עליו לפי הנראה מזה הספור. וכשמוע עבד אברהם דבריהם נתן תורה לשם יתעלה והשתחוה לו והוציא כלי כסף וכלי זהב ושמלות ונתן לרבקה ונתן מתנות חמודות מאד לאחיה ולאמה ולא לאביה כי אין זה ראוי לפי הנהוג והנה אכלו ושתו ולנו שם העבד והאנשי' אשר אתו וכאשר קמו בבקר אמר להם העבד שישלחוהו לאדוניו בשיתנו לו רבקה ויוליכה ליצחק. והנה בתואל לא סרב בזה אבל אחיה ואמה אמרו לרב האהבה הדמיונית אשר להם עמה שראוי שתשב הנערה אתם שנה או עשר חדשים להשביע עיניה מראיית אנשי בית אביה ומשפחתה ואחר תלך ואמנם אמרו זה לפי שהיא הולכת בארץ רחוקה מאד ולא יתכן שתשוב לראות בית אביה וחלה פניהם העבד שלא יאחרו אותי מלשוב לאדוניו כי השם הצליח דרכו ומאתו נהיה הדבר וכאשר ראו זה אמרו שישאלו לנערה אם תסכים ללכת עמו וכאשר שאלוה על זה אמרה להם שכבר תלך עמו ולא יקשה בעיניה הפרדה מבית אביה ושלחו אחר זה רבקה אחותם ומניקתה כי כן היה נהוג בימים ההם ושלחו עבד אברהם ואנשיו ברכו רבקה ואמרו לה אחותינו את היי לאלפי רבבה ויירש זרעך את שער אויביו ואמנם ברכוה בזאת הברכ' מפני שהיא הית' הולכ' בארץ לאלה ונפרדה ממשפחתה כי זה ממה שיביא למעט רבוי הזרע ושיהיה זרעה בזולת ארץ אם לא יירשו אנשי הארץ ההיא בדרך מלחמה והנה קמה רבקה ונערותיה הבאו' עמה לשרתה ותרכבנה על הגמלים ותלכנה אחרי עבד אברהם וכאשר היה עבד אברהם קרוב ממקום אדוניו לקח רבקה אתו לדקדק בענינה בבאה לפני אדוניו והלך עמה ואולם קודם זה היתה הולכת אחריו לרב הצניעות והנה יצחק בא מבא באר לחי רואי אשר בא שם להיות המקום ההו' נבחר כי סמוך למקום ההו' היה ביתו וזה שהו' היה יושב בארץ הדרום ושם היה באר לחי רואי כי הוא בארץ הנגב בין קדש ובין שור כמו שקדם ויצא' יצחק לשוח בשדה סמוך לשקיעה החמה ונש' עיניו ורא' והנה הגמלים באים ותשא רבק' עיניה וראת' יצחק והפילה עצמ' מעל הגמל אח' שהגיד לה העבד שהי' יצחק ולחקח' הצעיף ותתכס פניה לרוב צניעותה. וספר העבד ליצחק כל הדברים שעשה ואיך הצליח השם דרכו כדי שידע שלמות רבקה וטוב מוסדה ושהיא ממשפחתו והביאה יצחק האהלה אהל שרה אמו להיות' מתיחסת לה בטוב תכונותה ובנועם מוסרה ולקח רבקה והיתה לו לאשה ואהב אותה לשלמותה והתנחם בה מפני זה במה שנפקד ממנו במות אמו השלמה. ואחר זה הוסיף אברהם לקחת אשה ושמה קטורה וילדה לו בנים רבים. וכראות אברהם שלא היה בהם מי שידרוך אל השלמות נתן כל אשר לו ליצחק ונתן מתנות לבני קטורה והגר ושלחם מעל יצחק בנו בעודנו חי אל ארץ המזרח כדי שלא יריבו עם יצחק על הירושה ושלא ימנעוהו מהשלמות מפני רוע מעשיהם. וספר אחר זה שכבר היה ארם קע"ה שנה ואחר זה מת בגויעה בזולת צער ומת בשיבה טובה שכל ימיו היה השם עמו והיה זקן ושבע ימים ונאסף אל עמיו רוצה לומר שנשארה נפשו קיימת ונאספה אל אבותיו הטובים אשר היה להם חלק בזה ההשארות. ואפשר שנאמר שהרצון בו שהוא נאסף אל המושכלות אשר קנה בחייו וזה שהאדם מה שהתמיד שכלו להיות דבק בחמר לא יוכל להאסף אל המושכלות שהם עמו וזה כי מפני שהנפש היא אחת לא יוכל השכל להתבודד מבין שאר הכחות הנפשיות אל שישתמש באלו המושכלות יחד. אבל ישתמש בעת מה באחד מהם כשתשוטט מחשבתו בדבר ההוא ואולם אחר המו תיאסף השכל אל אלו המושכלות אשר קנה בחייו. והנה קרא אלו המושכלות עמים לפי שהם הסדור הכולל הנמצא למין מין מהמינים אשר יהיה המושכל ההוא מורה בהם וזה כלו מבואר מאד למי שעיין בדברינו בספר מלחמות השם. וספר אחר זה שכבר קברו אותו יצחק וישמעאל בניו במערת המכפלה ואחר מות אברם ברך השם יצחק והצליח קניניו. וישב יצחק אצל באר לחי רואי להיות המקום ההוא נבחר. וספר אחר זה תולדות ישמעאל בעבור כבוד אברהם ולהודיע האומות הרבות שהסתעפו ממנו ושכבר הוליד י"ב נשיאים כמו שייעד השם יתעלה לאברהם ולזה אמר שבני ישמעאל היו במעלה גדולה אצל אנשי הארץ שהיו שם עד ששמו אותם נשיאים עליהם והיו לאחד אחד מהם ערים מוקפות חומה ובלתי מוקפות. וספר שכבר מת ישמעאל בן קל"ז שנה בזולת צער ושכבר היה לו חלק בהשארות הנפש לפי שכבר השיג מהשלמות שיעור מה ואם הוא מעט והודיענו זה לכבוד אברהם. וספר שכבר היה לבני ישמעאל ארץ רחבה מאד עד שכבר שכנו מחוילה עד שור אשר על פני מצרים אצל מבוא אשור ונפל גורל ארצו אצל כל אחיו כמו שייעד השם יתעלה אל הגר והנה התועלות המגיעות מזה הספור הם רבים:

@1 **התועלת** הב' הוא במדות. והוא שראוי לאדם להשתדל בחריצות לקבור המתים שמוטלים עליו לקברם לכבוד החיים והמתים. ולזה תמצא שהשתדל אברהם בזה האופן מההשתדלות לקבור שרה אשתו:
@1 **התועלת** השלישי הוא במדות. והוא שראוי לאדם שיתרחק משיקבור הטובים אצל הרעים ולזה תמצא שאברהם אבינו השתדל לקנות אחוזת קבר לקבר שם מתו ולא רצה לקבר אשתו בקבר העם ההוא כי הם היו רעים מאד במנהגיה' כמו שהתפרסם מעניינם מהכנעני' כי החתי היה אחד ממשפחו' כנען. ותמצא גם כן בבנות חת שהיו מורת רוח ליצחק ולרבקה. והנה בזה תועלת להעיר שיש הבדל נפלא גם אחר המות בין הצדיק והרשע לפי שסוף הצדיק הוא אל החיים הנצחיים וסוף הרשע אל האבדון והכליון המוחלט:
@1 **התועלת** הד' להודיע גודל מעלת אברהם אצל אנשי הארץ ההיא עד שקראו אותו נשיא אלהים וכבדו אותו בזה האופן שהתבאר בזה הספור וזה לאות שכבר נתקיים מה שייעד ה' לאברהם ואגדלה שמך:
@1 **התועלת** הה' הוא במדות. והוא שראוי לאדם כשיצטרך לו דבר מה ישתדל בהגעתו בסבות אשר יתכן זה בהם יותר. ולזה תמצא שאברהם לא בקש תחלה לקנות כי אם המערה לחשבו שכבר יקשה לעפרון למכר נחלותיו. ולזה לא בקש ממנו כי אם ההכרחי לו לבד וחלה פני עם הארץ שיחלו פני עפרון על זה כדי שישיג מבוקשיו ממנו בקלות וכאשר הבין מעפרון שלא רצה למכרה לבדה השתדל עמו שימכרה לו עם השדה ונתן לו מה שהבין מדבריו שהוא רוצה מהשדה והמערה והוא ארבע מאות שקל כסף. וקנה זה הקניין בפני כל העם כדי שיהי קיים יותר:
@1 **התועלת** הששי הוא במדות. והוא שראוי לאדם כשיתן הכסף למי שיבוש לאמר לו שהכסף ההוא בלתי נבחר או שאין לו בו כל המספר שהסכי' לתת לו. שידקדק במספ' ושיהיה הכסף ההוא שיתן לו שלם במשקלו ונקי ונבחר. ולזה תמצא שאברהם כשראה שיבוש עפרון לאמר לו שאין כל הכסף שהשכי' לתת לו במה שנתן לו או שאינו במשקל ראוי או שאינו נקי התעורר מעצמו ונתן לו במשקל שלם ובמספר המסכם והיה כסף נקי ונבחר עד שהיה מתקבל לסוחר שהולך אנה ואנה:
@1 **התועלת** השביעי הוא במדות שאין ראוי לאדם לעשות בקרקעותיו דבר יגיע בו הזק או צער לשכניו אם לא בהסכמתם. ולזה תמצא שבקש אברהם מאת בני חת שיסכימו שיהיה לו השדה והמערה שבו אשר קנה לאחוזת קבר וכבר הוציאו ר"ל מזה השרש דינים רבים במקומות מבתרא:
@21 **התועלת** הא' הוא בדעות והוא שכבר העירנו בזה הספור שבכאן נמצא אחד הוא התחלת השמי' והארץ והוא מה שאמר ואשביעך ביי' אלהי השמים ואלהי הארץ והוא דבר טעו בו הרבה מהקודמים. וחשבו שהתחלת הדברים הנפסדים והם הדברים אשר בעולם השפל היא זולת התחלת הדברים הבלתי נפסדים והם הגרמים השמימיים לפי שהם חשבו שהתחלת הדברי' המתחלפים ראוי שתהיה מתחלפ' ולזה האמינו שבכאן שני אלוהות אלא שעם החקירה יתבאר שזה הדעת הוא נפסד כי אנחנו נראה המציאו' כלו מתאחד ונקשר קצו בקצתו וזה ממה שיחייב שיהיה כלו מהתחלה אחת במספר כמו שהתבאר במקומותיו:
@21 **התועלת** הב' הוא במדות. והוא שראוי לאדם להתרחק מהתחבר עם הפחותים לפי היכולת ולזה הרחיק אברהם שיקח יצחק אשרה מבנות כנען להיות מנהגיהם פחותים מאד כמו שהתפרסם מדברי התרה אמר וכמעשה ארץ כנען לא תעשו ואמנם הוכרח לשבת בארצם למצות השם יתעלה לסבה שזכרנו במה שקדם:
@21 **התועלת** השלישי הוא במדות. והוא שראוי להתחבר עם משפחתו בעניין הזווג כי בזה ישלם יותר בין הזרעי' האותות אל שתהיה מהם הולדה נאותה עם שההסכמה תשלם יותר בין האיש ואשתו כשהיו ממשפחה אחת ולזה שבחו רבותינו זכרונם לברכה הנושא בת אחותו וכבר העירנו בזה ממה שצוה אברהם אל העבד ללכת לארצו ולבחר ממנה אשה ליצחק ממולדתו:
@21 **התועלת** הרביעי הוא בדעות. והוא להעיר שמשגחת השם יתעלה תדבק באוהביו ובו יעזרו להשיג מה שיבקשו מהטוב ולזה נשען אברהם בשם ית' שיעזרהו להשיג מבוקשו כשתהיה ליצחק אשה מארצו באופן שיתכן שיהיה לו זרע נאות לירושת הארץ כמו שיעדו השם יתעלה:
@21 **התועלת** החמישי הוא במדות והוא שכאשר לא יוכל האדם להשיג הטוב השלם אין ראוי שיתרשל מההשתדלות בהשגה הטוב אשר למטה ממנו אבל ראוי שישתדל לקנות מהטוב כפי מה שאפשר לו ולזה התיר אברהם לאליעזר לקחת אשה ליצחק מבנות הכנענים אם היה שלא ימצא אשת מארץ אברהם שתאבה ללכת אחריו וזהו מה שאמר לו אם לא תאבה האשה ללכת אחריו בארץ הזאת יהיה נקי משבועתו אלא שאיך שיהיה העניין לא התיר לו להשיב יצחק שם לפי שרצון השם יתעלה היה שיעמוד בארץ כנען להיותה מוכנת יותר אל השלמות כמו שקדם:
@21 **התועלת** הששי הוא במדות. והוא שראוי לאדם שיכוין בדבר מה לתכלית מה שישתמש בזה בכל הסבות העוזרות להגעת התכלית הוא כפי מה שאפשר כי בזה ישלם לו יותר התכלית אשר כיון אליו. ולזה תמצא שלקח עבד אברהם עשרה גמלים מגמלי אדוניו ונשא עמו מטוב אדוניו חלק רב להראות האנשים הפלגת עושר אברהם כדי שיתרצו יותר לו לתת בתם לזאת הסבה גם כן נתן העבד לרבקה זאת המתנה שנתן לה עם הודעתו לבית בתואל שהוא עבד אברם כי זה ממה שיישב בנפשם עוצם עושר אברהם עד שכבר היה באופן שלא הקפיד על עבדו אם יתן כמו אלו המתנות ולזאת הסבה גם כן ספר אליעזר ללבן ובתואל ענין השבועה שהשביע אותו אברם שלא יקח ליצחק אשה מבנות הכנעני וזה כי לולי זה היה להם לחוש שמא לרוע מנהג יצחק או להעדר העשר מאברהם או לרוע מנהג ביתו לא מצא יצחק אשה בארץ אשר גר שם אברהם:
@21 **התועלת** השביעי הוא במדות. והוא שהמשרת השלם ראוי שישגיח מעצמו בענין השרות הראוי שישגיח ממנו קודם שיצוה עליו שאם לא יהיה בזה מושגח מעצמו לא ישלם ממנו השרות הראוי. ולזה תמצא שבחר אליעזר שתהיה תכונת האשה אשר יקח ליצחק זאת התכונה כדי שיגיע ממנה שדות שלם ליצחק וזה כי מפני שכבר השגיחה מעצמה לעשות שררות לא בוקש ממנה על צד החסד כ"ש שתהיה השגחתה בשרות בעלה שהוא חק עליה באופן יותר שלם.וכבר הורה שזאת התכונה היתה חזקה ברבקה שכבר תמצא באליעזר שלא שאל ממנה שתשקהו מים כי אם אחר עלותה מהעין והחזיקה בדרך לשוב לביתה ולא נמנעה מפני זה מהשקותו אליעזר מכדה ומלשאוב לכל גמליו. וזה גם כן עשתה בזריזות ובחריצות גדול ותמצא זה העניין נמשך מתכונתה בכל העניינים עד שכאשר שאל לה אם יוכל ללין בבית אביה השגיחה מעצמה בשאר הדברים הצריכים לו ואמרה גם תבן גם מספא רב עמנו גם מקום ללון:
@21 **התועלת** השמיני הוא במדות. והוא שראוי לנכבד כשגמלוהו טוב שישיב גמול לגומלים אותו ביותר משיעור הגמול אשר גמלוהו שעור רב ולזה תמצא שנתן אליעזר זאת המתנה לרבקה בעבור החסד שגמלה אותו. ואלו לא היה זה דבר ראוי היה מיוחס לאליעזר לסכלות לא לנדיבות וכבוד . ובכלל הנה אם לא ישיב מקבל הטוב גמול כי אם בשיעור מה שקבל הנה ישיב מה שהיה מההטבה והחנינה על צד החסד במדרגת מה שהיה בשכירות ובמחיר והיה פוחת מדרגת מה שנעשה לו על צד החסד. ואולם כשהיה מה שיגמול על ההטבה ההיא שיעור רב מאד מההטבה ההיא הנה לא יפחות מדרגת ההטבה הנעשית לו אבל תשאר מדרגתה מדרגת מה שנעשה על צד החסד והכבוד ובזה תהיה מדרגת הגמול שישיב על צד החסד והכבוד ותתחזק האהבה בזה בין הנותן והמקבל. והוא מבואר שאין ראוי גם כן שישיב לו יותר מעט ממה שקבל וזה כי כבר הטיב לו האחד קידם שיהיה לו עליו דבר יוכרח בעבור אל שייטיב לו וכאשר ישיב לו גמול הנה יוכרח בו מצד מה שישיב לו גמול כמוהו פעמים או יותר מצד מה שהקדימו מההטבה ולזה הוא מבואר שלא יספיק לו להראו' שרצונו עם המטיב לו במדרגת רצון המטיב לו עמו אם לא יוסיף במה שיגמלהו על השעור שהגיע לו ממנו כמו השיעור ההוא או יותר וזה מבואר בנפשו כל שכן שאין ראוי שישיב לו מעט תחת הרבה והוא מבואר שכל מה שהיתה מעלת הגומל יותר גדולה ראוי שיהיה הגמול שישיב יותר גדול כי האדם יראה לרעהו שהוא אוהבו בשיתן לו מה שהוא יקר ונכבד אצל הנותן:
@21 **התועלת** התשיעי הוא בדעות. והוא שראוי לאדם כישונו מחשבותיו ויצליחו עניניו שיודה לשם יתעלה אשר הכל מאתו כי בזה תועלת להתישר לעבודת השם יתע' ולהתקרב אליו כפי היכולת רצונו לומר כי כשיתפרסם שהשם יתע' משגיח במין האנושי בזה האופן ישתדלו האנשים לעבוד השם יתע' ולהתקרב אליו כפי היכולת כדי שיגיעם טוב ממנו מצד השגחתו בהם. ולזה תמצא שנתן אליעזר שבח והודאה לשם על הטוב אשר גמל לאברהם בזה הענין:
@21 **התועלת** העשירי הוא במדות. והוא שראוי לאדם שלא יתעצל במה שיכוין אבל ראוי שישתדל בהגעתו בחריצות ובזריזות כי העצלה אולי תמנע ממנו התכלית שכוון אלי ולזה תמצא שלא רצה אליעזר לאכול עד שדבר דבריו עם שבזה היה תועלת שנית וזה כי קודם שקבל הטובה מהם היה לו חק עליהם בעבור הטוב שהטיב להם אל שישמעו אליו למה שיבקש מהם יותר מהחק שיהיה לו עליהם אחר קבלו ההטבה מהם ולזה גם כן לא רצה לאכול עד כלותו העניין עמהם והנה נמשך מזריזות אליעזר וחריצותו שלא רצה להתעכב שם אחר השיגו מבוקשו אבל אמר להם שישלחוהו וילך אל אדוניו:
@21 **התועלת** האחד עשרה הוא במדות. והוא שאין ראוי להשיא אשה אם לא לדעתה ורצונה כי לא יאות להכריחה במה שלא תתרצה בו מזה שכבר יביאה זה לזנות בית אישה עם שאר ההפסדים אשר ימשכו מזה העניין בתקון הבית ולזה אמרו נקרא לנערה ונשאלה את פיה:
@21 **התועלת** השתים עשרה הוא במדות. והוא שראוי לאדם בלכתו עם אשה שילך ראשון והיא אחריו ואף על פי שתהיה באופן שיהיה ראוי לו לתת לה כבוד. וזה שאם היתה האשה הולכת תחלה יהיו עיני האדם בה ויביאהו זה לחשוק בה ויבא לידי עברה ולזה תמצא שהלכו רבקה נערותיה אחרי האיש עד הגיעם למקום אשר היה שם יצחק:
@21 **התועלת** הי"ג הוא בדעות. והוא שכבר נתיישר מתנועת הככבים על שיש שם מניע קודם להם הוא האלוה. ולזה תמצא שיצחק התפלל לשם יתע' בעת הערב כי אז נתברר לאנשי' שהשמש הוא מתנועע ויחוייב שיהיה שם מגיע קודם לו יניעהו. ולזאת הסבה בעינה התפלל אברהם להשם יתעלה בעת זריחת השמש וזה כי הכוכב אשר אפשר שיטעו בו האנשים יותר שיהיה אלוה הוא השמש כי פעולותיו בזה העולם השפל הם מפורסמות תכלית הפרסום. ולזה טעו הרבה מהקודמים וחשבו בו שהוא האלוה ולזה בחרו האבות הקדושים העתים אשר יתבאר לאנשים שהשמש הוא מתנועע להתפלל לשם יתע' וזה כי בעת הזריחה והערב יתבאר תכלית הבאור שהשמש הוא מתנועע כי הוא זורח ביום אחד בזולת מקום זריחתו ביום השני וכן העניין בשקיעה ואם היה גלגל השמש קיים והארץ מתנועעת כמו שחשבו אנשים רבים היתה זריחת השמש תמיד במקום אחד מהאופק וכן העניין בשקיעתו. ולזה הוא מבואר שזריחת השמש ושקיעתו תורה על שהשמש מתנועע עם כל גלגל השמש. והנה אברהם בחר עת הזריחה לזאת הסבה כאשר ראה יצחק שפעל השמש הולך וחזק בזה העת והוא הצד אשר בעבורו חשבו הקדמונים שיהיה השמש הוא האלוה בחר עת שקיעת השמש להתפלל לשם ית' לפי שאז יחלש כח פעל השמש וזה ממה שיורה שאין השמש הוא האלוה כי לא יתכן באלוה שיחזק פעם ויחלש פעם. ויעקב בחר להתפלל לשם יתעלה אחר שקיעת השמש לפי מה שהבינו קצתם ז"ל ממה שאמר ויפגע במקום וילן שם כי בא השמש לפי שאז יראו כוכבים רבים וזה ממה שיורה שאינן אלוהות כי לא יתכן שתשלם מאלוהות רבים הנהגת העולם אחד במספר כי ההנהגה בדבר א' במספר יחוייב שתהיה מסודרת מאחד במספר ולזה הוא מבואר שראוי שיהיו כל הכוכבים עלולים מעלה אחת הוא האלוה כי המאמר כשיהיה האחד מהם הוא הראשון והאחרים הם משרתים לו הוא מבואר הבטול כי הם כלם מטבע אחד עם שזה המאמר הוא גם כן מבואר הבטול כמו שהתבאר בחמישי מספר מלחמות יי'. והנה עם כל זה כלל העת שהתפלל בו יעקב ההוראה שהכוכבים הם כלם מתנועעים כי יראה כשהשלים השמש הסבוב היומי שלא יראו הככבים הקיימים הזורחים בערב האחד שישובו לזרוח בערב השני. אבל יראו גבוהים על האופק וזה ממה שיורה שאין התנועה הנראית להם שוה לתנועה אשר יראה לשמש. ואלו היו הככבים קיימים והארץ מתנועעת היתה התנועה הנראית לככבים כלם שוה. והנה תמצא שלזאת הסבה צוה השם יתע' בהבאת הקרבן בר"ח ובר"ה כי אלו העתים יורו על שהככבים מתנועעים ושזאת התנועה תלך בסבוב. וזה כי בר"ח ידבקו השמש והירח ואחר יעבור הירח השמש עד שישוב להתדבק עמו בר"ח שני. וכן מקום זריחת השמש ושקיעתו בר"ה תשוב במקום שהיתה בר"ה השנית באופן ההוא שהיתה בשנה הקודמת כאו תאמר שתטה מעט מעט אל הצפון עד שתהיה בתכלית הנטייה הצפוניית. עוד תטה מעט אל הדרום עד שתהיה בתכלית הנטייה הצפוניית. עוד תטה מעט אל הדרום עד שתהיה בתכלית הנטיה הדרומית עוד תתקרב אל משוה היום עד שתדבק בו בר"ה:
@21 **התועלת** הי"ד הוא במדות. והיא שראוי לאשה שתבוש מבעלה וכ"ש בתחלת לקיחתו אותה יותר מבשתה משאר האנשים לפי שהוא ידוע כי לקיחתה האיש הוא למשגל והנה ראוי שתבוש האשה מזה. ולזה תמצא שכבר לקחה רבקה הצעיף ותתכס כשידעה שהאיש ההולך בשדה הוא יצחק. וזה כי כבר יורה כי כאשר אין האשה בושה מזה שאין המשגל אצלה דבר ראוי שתבוש ממנו ותהיה בזה ראיה על שלא הקפידה לשמור עצמה ממשכב הדודים:
@21 **התועלת** החמש עשרה הוא במדות. והוא שראוי לאדם שיזרע בבקר זרעו ולערב אל יניח ידו כי בזה ישלם קיום המין האנושי. ולזה תמצא שאברהם אבינו הוסיף לקחת אשה להוליד בנים עם היותו מופלג בזקנה:
@21 **התועלת** השש עשרה הוא במדות. והוא שראוי לאדם להרחיק המריבה מבניו בעניין הנחלה לפי מה שאפשר ולזה תמצא שאברהם נתן לבניו בחייו מה שישר בעיניו לתת להם והרחיקם מעל יצחק כדי שלא יריבו עמו על הנחלה להיותו יורש כל הנכסי' עם שכבר נמשך מזה תועלת אחר והוא שלא ילמד יצחק ממעשיהם הרעים כי בו בחר השם יתעלה להיות ממנו הזרע הנבחר שיירש ארץ כנען:
@21 **התועלת** השבע עשרה הוא בדעות. והוא להודיע שהצדיקים הם מושגחים כשימלא השם יתע' מספר ימיהם ויבלו ימיהם בטוב ולזה ספר שכבר חיה אברהם קמ"ה שנה ואח"כ מת בשיבה טובה זקן ושבע ימים:
@21 **התועלת** השמונה עשרה הוא בדעות. והוא להודיע שהשכל הנקנה ישאר אחר המות והוא מה שהשיג האדם בחייו מן המושכלות ושאז ישיג האדם יחד כל מה שהשיג בחייו כי אין לו מונע מזה מצד החמר מהשגת אלו המושכלות. ולזה ספר שכבר נאסף אברהם אחר המות אל המושכלות הכוללות אשר השיג בחייו וזה התועלת הוא רב מאד כי בו טעו הפילוסופים כלם כמו שהתבאר מדבריהם וחשבו שהשכל הנקנה הוא נפסד במות האדם. וזה הדעת הנפסד הוא מה שירחיק האדם משלמותו הרחקה נפלאה כמו שבארנו בראשון מספר מלחמות יי'. והנה קרא אלו המושכלות עמים על דרך אמרו מרכבות עמינדיב כמו שבארנו לבאורנו בשיר השירים והיה זה כן לפי שתיבת עם תאמר על אי זה קבוץ וכללות. אמר עמים הר יקראו רמז אל השבטים לעם נכרי רמז אל קבוץ הבית:
@21 **התועלת** התשע עשרה הוא במדות. והוא שראוי לבנים שיתעסקו בקבורת אביהן לכבודו ובמקום שהסכים להקבר שם ולזה תמצא שקברו יצחק וישמעאל אברהם במערת המכפלה.
@21 **התועלת** העשרים להודיע מעלת יצחק ושכבר היה באופן מהשלמות שדבקה בו השגחת השם יתעלה אחרי מות אברהם. ולזה ספר שכבר ברך אותו השם יתעלה אחרי מות אברהם ולזה גם כן ספר שכבר בחר יצחק לשבת במקום שיהיה ראוי שידבק לו השפע האלהי והוא באר לחי רואי:
@21 **התועלת** העשרים ואחד להודיע מעלת האבות אצל אנשי הארץ אשר גרו שם עד שכבר תמצא שבני ישמעאל היו כלם נשיאים בעלי עיירות מוקפות חומה ובלתי מוקפו' חומה עם שכבר הודיענו בזה הספור שכבר נתקיים היעוד שיעד השם יתעלה לאברהם מבנו ישמעאל שכבר יוליד י"ב נשיאים ומה שיעד גם כן שכבר ישכון ישמעאל אצל כל אחיו והודיענו גם כן בזה הספור איך נסתעפו מאב אחד אלו האומות אשר היו מפורסמות בזמן נתינת התורה כדי שלא יפיל זה הענין ספק על מה שנזכר בתורה מענין חדוש העולם כמו שזכרנו בפרשת בראשית:

@106 **והמלך דוד זקן.** עד ויתחתן שלמה את בת פרעה: **ויכסוהו בבגדים ולא יחם לו.** ידוע שהבגדים אינם מחממים כ"א במקרה מצד שמירתם שהאויר המקיף בגוף לא יקררהו ולזה בקשו לו עבדיו דבר שיחממהו מצד חמימות בו ובחרו לו שיתחמם בחום נערה בתולה מפני שיתקבצו סבות רבות אל שתחממהו האחת מצד אשר בה והשנית מצד התחממה בהיותה עם הזכר והתעוררה למשגל והשלישית כי הוא ג"כ יתעורר טבעו לקראתם מצד יפיה והיותה בתולה וזה יהיה סבה אל שיתחמם מעצמו:
@107 **ותהי לו סוכנת.** ר"ל שומרת האוצרות וזה יהיה סבה שתוכל לבוא לשכב בחיקו ואיש לא ירגיש:
@110 **ויעש לו רכב ופרשים וחמשים איש רצים לפניו.** ראוי שתדע שמלכי ישראל לא הותר להם להרבות סוסים ולזה לא היה זה הענין קטן אצל מלכי ישראל:
@111 **ולא עצבו אביו מימיו לאמר מדוע ככה עשית.** הנה מפני זה חשב אדניה שיהיה לב דוד להמליכו אחריו כי לא גנה אותו על דבר ממעשיו והוא היה גם כן יפה תאר מאד ובעבוד יפיו חשב שהוא ראוי למלך: **ואותו ילדה אחרי אבשלום.** הנה הוא מבואר שאי אפשר שנבין מזה ענין הלידה כי אבשלום היה בן מעכה ואדניה היה בן חגית ואילו היה מענין הלידה היה ראוי שיהיו שניהם מאם אחת תלד אדניה אחרי אבשלום ולזה הוא מבואר שהוא מענין הגדול כאמרו ואת חמשת בני מיכל בת שאול אשר ילדה לעדריאל המחולתי שהוא מענין הגדול כמו שקדם והרצון בזה שאמו גדלה אותו אחרי אבשלום והתנהג במנהגיו ובמדותיו ולזה אמר וגם הוא טוב תאר מאד כמו אבשלום שהיה יפה תאר מאד כמו שזכר במה שקדם הנה כמו שחשב אבשלום שימלוך אחר דוד מפני רוב יופיו כמו שחשב אדניה:
@112 **ויהיו דבריו עם יואב בן צרויה ועם אביתר הכהן.** ר"ל שכבר משך את לבבם להמשיך ולהסכים להמליכו והם עזרוהו בזה והנה חשב שכמו שאלו עזדו לדוד להגיעו למלכות ולהצליח כן יגיע לו על ידם וזה כי אביתר בא אל דוד מפני ברחו מפני שאול ועל פיו היה עושה דוד כל מעשיו ויואב הקים דוד על כסא המלוכה ונלחם מלחמותיו עם איש בשת ואבשלום ושבע בן בכרי ויואב גם כן נמשך לאדניה ועזרהו על הממלכה כדי שיאהבהו ולא יסירהו מהיות שר צבא כי נתבאד לו כי לב דוד להסירו ממעלתו בעבור דבר אבשלום ואביתר הכהן גם כן ראה כי דוד היה נותן יותר מהכבוד והמעלה לצדוק ממה שהיה נותן לאביתר וזה מבואר מהספורי' הקודמים שהקדים בהם דוד צדוק לאביתר:
@114 **ומריא.** הוא מין ממיני הבקר השמנים והגדולי': **עם אבן הזוחלת.** ר"ל אצל אבן הזוחלת ונקראת האבן ההיא כך לסבה לא ידענוה ואפשר כי האבן ההיא היתה גדולה וחלקה מאד ולרוב חלקותיה היו מניעין אותה הנה והנה:
@115 **והנה** לא קרא שלמה אחיו לאכל עמו כי ידע שהוא ינגד לו בזה להיותו בוטח שימלוך אחרי דוד אביו ולזאת הסבה גם כן לא קרא אל נתן הנביא כי הוא נבא לדוד ששלמה ימלוך אחריו כמו שנזכר בדברי הימים ובכלל הנה לא קרא לאותם שלא היו נסכמים לעצתו כמו צדוק הכהן ובניהו בן יהוידע ונתן הנביא ושמעי ורעי והגבורים אשר לדוד כי ידע כי הם יבלבלו עצתו ותתחדש מזה תנואת לב העם הנסכמים לעצתו:
@119 ומלאתי את דבריך. אשלים מה שיחסר בהם או ירצה בזה שימשך לדבריה כטעם כי מלא אחרי ה':
@126 **והייתי אני ובני שלמה חטאים.** ר"ל נענשים כי מפני שידע אדניהו כי הממלכה עתידה להיות לשלמה ישתדל להמיתו כמו שהי' מבקש שאול להרוג את דוד לזאת הסבה עם שזה יהיה סבה להזכיר חטא בת שבע אחרי מות דוד ויביא זה לעז ג"כ על שלמה ואולם אם ימלוך שלמה יתבאר לכל כי מה' היתה בת שבע לדוד ושלא היתה אסורה לו אחרי מות אוריה עם שמפני אימת מלך ייראו לאמר דבר כנגדו או יהי' הרצון בזה והייתי אני ובני שלמה חטאים אם לא נגלה אזנך על זה בחייך כי נעשוק ממנו המתנה הטובה שנתת לנו ולא יהיה האשם זולתי בנו להגלות הענין שדעתך היא להמליכנו כאשר דברת ונשבעת לאמתך:
@129 **אתה אמרת אדניה ימלוך אחרי.** ר"ל האם אתה אמרת אם מאת אדני המלך נהיה הדבר הזה ולא הודעת את עבדך ר"ל האם היה מאת אדני המלך הדבר הזה ולא קראו לי כי לא הסכמת להודיע לעבדך מי ישב על כסאך:
@133 **ויען המלך דוד ויאמר קראו לי לבת שבע.** הנה נראה מזה כי בת שבע יצאה מן החדר בבא נתן הנביא לדבר אל המלך כדי שלא יכיר המלד כי זה הדבר היה מוסכם ביניהם ולזה קרא דוד לבת שבע ופחד לבא אליה ולומר אלו הדברים כי היא היתה יותר עצמית בזה מנתן הנביא כמו שמצאנו באשה התקועית שעשתה שאמרה הדברים אל יואב לא אליה:
